// 🌸 金句資料檔（JS語錄產生器）
// 平常不用動這個檔；只有「新增、修改、刪除金句」時才改它。改完要和 index.html、sw.js 一起上傳到 GitHub（版本號三處要一致）。
// 規則見 CLAUDE.md「金句資料規則」：共 475 句、編號連續（#1 ~ #475）、關鍵詞共 100 個、每個關鍵詞至少 3 句、每句至少 3 個關鍵詞。
// 每句欄位：id（＝origId＝編號）、content（卡片文字）、semanticTags（關鍵詞）、lines（問候圖的畫布斷句）。
var aphorismsData = [
    {id:1, origId:1, content:"口說好話，心想好意，身行好事，腳走好路。", semanticTags:["說話","善念","行動"], lines:["口說好話，心想好意，", "身行好事，腳走好路。"]},
    {id:2, origId:2, content:"理直要氣和，得理要饒人。", semanticTags:["包容","修養","原諒","處事","衝突"], lines:["理直要氣和，", "得理要饒人。"]},
    {id:3, origId:3, content:"太陽光大，父母恩大，君子量大。", semanticTags:["父母","感恩","孝順"], lines:["太陽光大，","父母恩大，","君子量大。"]},
    {id:4, origId:4, content:"話多不如話少；話少不如話好。", semanticTags:["說話","溝通","謹慎"], lines:["話多不如話少；","話少不如話好。"]},
    {id:5, origId:5, content:"做好事不能少我一人，做壞事不能多我一人。", semanticTags:["本份","自律","付出"], lines:["做好事不能少我一人，","做壞事不能多我一人。"]},
    {id:6, origId:6, content:"要原諒一個無心傷害的人，不能做一個輕易被傷害的人。", semanticTags:["原諒","包容","勇氣"], lines:["要原諒一個無心傷害的人，","不能做一個輕易被傷害的人。"]},
    {id:7, origId:7, content:"聰明的人得失心重；有智慧的人勇於捨得。", semanticTags:["智慧","得失","解脫"], lines:["聰明的人得失心重；","有智慧的人勇於捨得。"]},
    {id:8, origId:8, content:"塵世裡最貴重的禮物是原諒。", semanticTags:["原諒","包容","珍惜"], lines:["塵世裡最貴重的","禮物是原諒。"]},
    {id:9, origId:9, content:"一個人的快樂，不是因為他擁有得多，而是因為他計較得少。", semanticTags:["快樂","知足","自由"], lines:["一個人的快樂，","不是因為他擁有得多，","而是因為他計較得少。"]},
    {id:10, origId:10, content:"對社會與其擔心，不如化作信心，更要付出一份愛心。", semanticTags:["付出","信心","愛心"], lines:["對社會與其擔心，","不如化作信心，","更要付出一份愛心。"]},
    {id:11, origId:11, content:"真正的愛心，是照顧好自己的這顆心。", semanticTags:["愛心","自愛","心情"], lines:["真正的愛心，","是照顧好自己的這顆心。"]},
    {id:12, origId:12, content:"做人要立好志，發好願。", semanticTags:["做人","方向","堅持"], lines:["做人要立好志，","發好願。"]},
    {id:13, origId:13, content:"原諒別人就是善待自己。", semanticTags:["原諒","自愛","解脫"], lines:["原諒別人就是善待自己。"]},
    {id:14, origId:14, content:"生氣是一種瘋病，醜化了自己。", semanticTags:["生氣","修養","自律"], lines:["生氣是一種瘋病，","醜化了自己。"]},
    {id:15, origId:15, content:"人生最大的成就，是從失敗中站立起來。", semanticTags:["失敗","成就","勇氣"], lines:["人生最大的成就，","是從失敗中站立起來。"]},
    {id:16, origId:16, content:"唯其尊重自己的人，才更勇於縮小自己。", semanticTags:["尊嚴","謙虛","自愛"], lines:["唯其尊重自己的人，","才更勇於縮小自己。"]},
    {id:17, origId:17, content:"有智慧才能分辨善惡邪正；有謙虛才能建立美滿人生。", semanticTags:["智慧","謙虛","幸福","家庭"], lines:["有智慧才能分辨善惡邪正；","有謙虛才能建立美滿人生。"]},
    {id:18, origId:18, content:"即使已達智慧圓融，更應含蓄謙虛，像稻穗一樣，米粒愈飽滿垂得愈低。", semanticTags:["謙虛","修養","做人"], lines:["即使已達智慧圓融，", "更應含蓄謙虛，", "像稻穗一樣，", "米粒愈飽滿垂得愈低。"]},
    {id:19, origId:19, content:"待人退一步，愛人寬一寸，在人生的道路中就會活的很快樂。", semanticTags:["快樂","包容","禮讓"], lines:["待人退一步，愛人寬一寸，","在人生的道路中就會活的很快樂。"]},
    {id:20, origId:20, content:"人要自愛，才能愛普天下的人。", semanticTags:["自愛","大愛","付出"], lines:["人要自愛，","才能愛普天下的人。"]},
    {id:21, origId:21, content:"時間可以造就人格，成就事業，也可以儲積功德。", semanticTags:["時間","事業","功德"], lines:["時間可以造就人格，","成就事業，","也可以儲積功德。"]},
    {id:22, origId:22, content:"人的心地就像一畝田。土地沒有播下好種子，也長不出好的果實來。", semanticTags:["善念","心情","改變"], lines:["人的心地就像一畝田。", "土地沒有播下好種子，", "也長不出好的果實來。"]},
    {id:23, origId:23, content:"能付出愛心就是福；能消除煩惱就是慧。", semanticTags:["付出","愛心","煩惱"], lines:["能付出愛心就是福；","能消除煩惱就是慧。"]},
    {id:24, origId:24, content:"不能低頭的人，是因為一再回顧過去的成就。", semanticTags:["成就","謙虛","反省"], lines:["不能低頭的人，","是因為一再回顧過去的成就。"]},
    {id:25, origId:25, content:"柔能調服眾生；剛能堅強己志。", semanticTags:["毅力","堅持","修養"], lines:["柔能調服眾生；","剛能堅強己志。"]},
    {id:26, origId:26, content:"人能和，則是非不生。", semanticTags:["平靜","衝突","處事"], lines:["人能和，","則是非不生。"]},
    {id:27, origId:27, content:"不要爭面子。爭來的是假的，培養來的才是真的。", semanticTags:["修養","人格","反省"], lines:["不要爭面子。", "爭來的是假的，", "培養來的才是真的。"]},
    {id:28, origId:28, content:"人事的艱難與琢磨，就是一種考驗。", semanticTags:["考驗","磨練","困難"], lines:["人事的艱難與琢磨，","就是一種考驗。"]},
    {id:29, origId:29, content:"是非當教育，讚美作警惕，嫌棄當反省，錯誤作經驗。", semanticTags:["反省","讚美","教育"], lines:["是非當教育，","讚美作警惕，","嫌棄當反省，","錯誤作經驗。"]},
    {id:30, origId:30, content:"任何批評都是寶貴的一課。", semanticTags:["批評","學習","反省"], lines:["任何批評都是寶貴的一課。"]},
    {id:31, origId:31, content:"人如不知足，就永遠都在煩惱中。", semanticTags:["知足","煩惱","欲望"], lines:["人如不知足，","就永遠都在煩惱中。"]},
    {id:32, origId:32, content:"人生的煩惱，是不分貧富貴賤的。透過煩惱轉成智慧，這個煩惱才有意義。", semanticTags:["智慧","煩惱","轉念"], lines:["人生的煩惱，","是不分貧富貴賤的。","透過煩惱轉成智慧，","這個煩惱才有意義。"]},
    {id:33, origId:33, content:"有心就有福，有願就有力。", semanticTags:["堅持","信心","幸福"], lines:["有心就有福，","有願就有力。"]},
    {id:34, origId:34, content:"脾氣嘴巴不好，心地再好，也不能算是好人。", semanticTags:["生氣","說話","修養","做人"], lines:["脾氣嘴巴不好，","心地再好，","也不能算是好人。"]},
    {id:35, origId:35, content:"不要把能說話的嘴巴，用在搬弄是非上。", semanticTags:["說話","謹慎","修養"], lines:["不要把能說話的嘴巴，","用在搬弄是非上。"]},
    {id:36, origId:36, content:"對人要寬心，講話要細心。", semanticTags:["說話","體諒","謹慎"], lines:["對人要寬心，","講話要細心。"]},
    {id:37, origId:37, content:"原諒別人是美德，原諒自己是損德。", semanticTags:["原諒","反省","修養"], lines:["原諒別人是美德，","原諒自己是損德。"]},
    {id:38, origId:38, content:"大錯誤容易反省，小習氣不易除掉。", semanticTags:["反省","改過","自律"], lines:["大錯誤容易反省，","小習氣不易除掉。"]},
    {id:39, origId:39, content:"生氣，就是拿別人的過錯來懲罰自己。", semanticTags:["生氣","轉念","包容"], lines:["生氣，就是拿別人的", "過錯來懲罰自己。"]},
    {id:40, origId:40, content:"一般人常說要爭一口氣。其實真正有工夫的人，是把這口氣嚥下去。", semanticTags:["轉念","自律","修養"], lines:["一般人常說要爭一口氣。","其實真正有工夫的人，","是把這口氣嚥下去。"]},
    {id:41, origId:41, content:"多做多得，少做多失。", semanticTags:["付出","行動","本份"], lines:["多做多得，","少做多失。"]},
    {id:42, origId:42, content:"甘願做，歡喜受。", semanticTags:["歡喜","付出","態度"], lines:["甘願做，","歡喜受。"]},
    {id:43, origId:43, content:"口說一句好話，如口出蓮花；口說一句壞話，如口出毒蛇。", semanticTags:["說話","讚美","謹慎"], lines:["口說一句好話，如口出蓮花；","口說一句壞話，如口出毒蛇。"]},
    {id:44, origId:44, content:"一個人不怕錯，就怕不改過；改過並不難。", semanticTags:["改過","勇氣","反省"], lines:["一個人不怕錯，","就怕不改過；","改過並不難。"]},
    {id:45, origId:45, content:"不經一事，不長一智。", semanticTags:["經驗","智慧","學習"], lines:["不經一事，","不長一智。"]},
    {id:46, origId:46, content:"智慧是從人與事之間磨練出來的。", semanticTags:["智慧","磨練","經驗"], lines:["智慧是從人與事","之間磨練出來的。"]},
    {id:47, origId:47, content:"吃苦了苦，苦盡甘來；享福了福，福盡悲來。", semanticTags:["磨練","得失","珍惜"], lines:["吃苦了苦，苦盡甘來；","享福了福，福盡悲來。"]},
    {id:48, origId:48, content:"人因自覺而成長，因自滿而墮落。", semanticTags:["反省","謙虛","學習"], lines:["人因自覺而成長，","因自滿而墮落。"]},
    {id:49, origId:49, content:"不要小看自己，因為人有無限的可能。", semanticTags:["信心","勇氣","自愛"], lines:["不要小看自己，","因為人有無限的可能。"]},
    {id:50, origId:50, content:"做個手心向下的人，不要做手心向上的人。", semanticTags:["付出","大愛","做人"], lines:["做個手心向下的人，","不要做手心向上的人。"]},
    {id:51, origId:51, content:"道德是提昇自我的明燈，不該是呵斥別人的鞭子。", semanticTags:["自律","反省","包容"], lines:["道德是提昇自我的明燈，","不該是呵斥別人的鞭子。"]},
    {id:52, origId:52, content:"信心、毅力、勇氣三者具備，則天下沒有做不成的事。", semanticTags:["勇氣","信心","毅力","準備"], lines:["信心、毅力、勇氣三者具備，","則天下沒有做不成的事。"]},
    {id:53, origId:53, content:"任何事都是從一個決心、一粒種子開始。", semanticTags:["堅持","信心","行動"], lines:["任何事都是從","一個決心、","一粒種子開始。"]},
    {id:54, origId:54, content:"閒人無樂趣，忙人無是非。", semanticTags:["時間","工作","本份"], lines:["閒人無樂趣，","忙人無是非。"]},
    {id:55, origId:55, content:"改變自己是自救，影響別人是救人。", semanticTags:["轉念","自愛","改變"], lines:["改變自己是自救，","影響別人是救人。"]},
    {id:56, origId:56, content:"願要大，志要堅，氣要柔，心要細。", semanticTags:["毅力","修養","謹慎"], lines:["願要大，志要堅，","氣要柔，心要細。"]},
    {id:57, origId:57, content:"雙手健全卻不肯做事的人，等於是沒有手的人。", semanticTags:["行動","工作","本份"], lines:["雙手健全卻不肯做事的人，", "等於是沒有手的人。"]},
    {id:58, origId:58, content:"弱者等待時機，強者創造時機。", semanticTags:["勇氣","行動","機會"], lines:["弱者等待時機，","強者創造時機。"]},
    {id:59, origId:59, content:"發脾氣是無能的表現。", semanticTags:["生氣","修養","自律"], lines:["發脾氣是無能的表現。"]},
    {id:60, origId:60, content:"看別人不順眼時，就要調整自己。", semanticTags:["轉念","反省","改變"], lines:["看別人不順眼時，","就要調整自己。"]},
    {id:61, origId:61, content:"忍得過、看得透、提得起、放得下。", semanticTags:["解脫","轉念","包容"], lines:["忍得過、看得透、","提得起、放得下。"]},
    {id:62, origId:62, content:"水滴雖微，漸盈大氣。", semanticTags:["堅持","毅力","時間"], lines:["水滴雖微，","漸盈大氣。"]},
    {id:63, origId:63, content:"前腳踏出去，後腳要跟著放開。", semanticTags:["解脫","轉念","自由"], lines:["前腳踏出去，","後腳要跟著放開。"]},
    {id:64, origId:64, content:"人的眼睛長在前面，只看到別人的缺點，絲毫看不到自己的缺點。", semanticTags:["反省","改過","批評"], lines:["人的眼睛長在前面，","只看到別人的缺點，","絲毫看不到自己的缺點。"]},
    {id:65, origId:65, content:"施比受更有福。", semanticTags:["付出","歡喜","幸福"], lines:["施比受更有福。"]},
    {id:66, origId:66, content:"真正的快樂是施捨後的那份清靜、安慰與喜悅。", semanticTags:["快樂","付出","平靜"], lines:["真正的快樂是","施捨後的那份","清靜、安慰與喜悅。"]},
    {id:67, origId:67, content:"要做個受歡迎、被愛的人，必須先照顧好自己的聲和色，面容動作、言談舉止，都是在日常生活中修養忍辱得來。", semanticTags:["修養","態度","禮讓"], lines:["要做個受歡迎、被愛的人，", "必須先照顧好自己的聲和色，", "面容動作、言談舉止，都是在", "日常生活中修養忍辱得來。"]},
    {id:68, origId:68, content:"多一次原諒別人就多一次福，把量放大福就大。", semanticTags:["原諒","包容","大愛"], lines:["多一次原諒別人就多一次福，","把量放大福就大。"]},
    {id:69, origId:69, content:"有心就有福，有願就有力；自造福田，自得福緣。", semanticTags:["自律","堅持","考驗","功德","付出","命運"], lines:["有心就有福，有願就有力；","自造福田，自得福緣。"]},
    {id:70, origId:70, content:"說話要謹慎、委婉：面對知音，不必說就懂；不是知音，說得再露骨也沒用。", semanticTags:["謹慎","說話","溝通"], lines:["說話要謹慎、委婉：","面對知音，不必說就懂；","不是知音，說得再露骨也沒用。"]},
    {id:71, origId:71, content:"轉一個角度來看世界，世界無限寬大；換一種立場待人處事，人事無不輕安。", semanticTags:["轉念","包容","處事"], lines:["轉一個角度來看世界，", "世界無限寬大；", "換一種立場待人處事，", "人事無不輕安。"]},
    {id:72, origId:72, content:"能忍而不計較，則再大的困難也能克服。", semanticTags:["克服","困難","包容"], lines:["能忍而不計較，","則再大的困難也能克服。"]},
    {id:73, origId:73, content:"自己害自己，莫過於亂發脾氣。", semanticTags:["生氣","自律","反省"], lines:["自己害自己，","莫過於亂發脾氣。"]},
    {id:74, origId:74, content:"凡夫迷失於當下，後悔於過去；聖人覺悟於當下，解脫於未來。", semanticTags:["選擇","解脫","時間"], lines:["凡夫迷失於當下，","後悔於過去；","聖人覺悟於當下，","解脫於未來。"]},
    {id:75, origId:75, content:"擁有是負擔，不計較就自在；能放下煩惱才能快樂。", semanticTags:["快樂","煩惱","知足"], lines:["擁有是負擔，","不計較就自在；","能放下煩惱才能快樂。"]},
    {id:76, origId:76, content:"君子為目標，小人為目的。", semanticTags:["做人","方向","修養"], lines:["君子為目標，","小人為目的。"]},
    {id:77, origId:77, content:"一句不恰當的話，就會使人產生排斥的心。", semanticTags:["說話","溝通","謹慎"], lines:["一句不恰當的話，","就會使人產生排斥的心。"]},
    {id:78, origId:78, content:"說話講得恰到好處，多一句少一句都不行。", semanticTags:["說話","處事","謹慎"], lines:["說話講得恰到好處，","多一句少一句都不行。"]},
    {id:79, origId:79, content:"憤怒能剝奪一個人的洞察力及忍耐力，惹起一切的罪惡，吞服一切後果，像猛火一樣地毀滅一個玩火的人。", semanticTags:["生氣","平靜","自律"], lines:["憤怒能剝奪一個人的洞察力及忍耐力，","惹起一切的罪惡，吞服一切後果，","像猛火一樣地毀滅一個玩火的人。"]},
    {id:80, origId:80, content:"孝順就是在父母需要你的時候，能歡喜付出。", semanticTags:["孝順","父母","付出","歡喜"], lines:["孝順就是在父母需要","你的時候，能歡喜付出。"]},
    {id:81, origId:81, content:"一句溫暖的話，就像往別人身上灑香水，自己也會沾上兩三滴。", semanticTags:["說話","溫暖","讚美"], lines:["一句溫暖的話，就像","往別人身上灑香水，","自己也會沾上兩三滴。"]},
    {id:82, origId:82, content:"教導別人也要分內外：對內要正，對外要柔。", semanticTags:["教育","溝通","態度"], lines:["教導別人也要分內外：","對內要正，對外要柔。"]},
    {id:83, origId:83, content:"勇氣不可失，信心不可無，世間沒有不能與無能的事，只怕不肯。", semanticTags:["勇氣","信心","堅持"], lines:["勇氣不可失，信心不可無，","世間沒有不能與無能的事，","只怕不肯。"]},
    {id:84, origId:84, content:"愈能忍受艱難的花，愈能有甜蜜的果。", semanticTags:["考驗","成就","磨練"], lines:["愈能忍受艱難的花，","愈能有甜蜜的果。"]},
    {id:85, origId:85, content:"知識要用心體會，才能變成自己的智慧。", semanticTags:["智慧","專注","學習"], lines:["知識要用心體會，","才能變成自己的智慧。"]},
    {id:86, origId:86, content:"能善用時間的人，必能掌握自己努力的方向。", semanticTags:["時間","方向","努力"], lines:["能善用時間的人，","必能掌握自己努力的方向。"]},
    {id:87, origId:87, content:"每天無所事事，是人生的消費者；積極有用，才是人生的創造者。", semanticTags:["時間","本份","工作"], lines:["每天無所事事，","是人生的消費者；","積極有用，","才是人生的創造者。"]},
    {id:88, origId:88, content:"一個人要點亮自己的心光，才能去引發別人。", semanticTags:["改變","希望","光明"], lines:["一個人要點亮自己的心光，","才能去引發別人。"]},
    {id:89, origId:89, content:"把他人拿來做自己的鏡子。看他人的優點，自我鞭策；看別人的缺點，反省自己。", semanticTags:["反省","學習","讚美"], lines:["把他人拿來做自己的鏡子。","看他人的優點，自我鞭策；","看別人的缺點，反省自己。"]},
    {id:90, origId:90, content:"愛不是要求對方，而是要由自身的付出，無條件地奉獻，做到事事圓滿。", semanticTags:["付出","愛心","無私"], lines:["愛不是要求對方，", "而是要由自身的付出，", "無條件地奉獻，", "做到事事圓滿。"]},
    {id:91, origId:91, content:"凡事往好的方面想，心中常存善念，遇事逢凶化。", semanticTags:["善念","轉念","樂觀"], lines:["凡事往好的方面想，","心中常存善念，","遇事逢凶化。"]},
    {id:92, origId:92, content:"你好我也好，一個人不但要看重自己，也要懂得欣賞別人。", semanticTags:["欣賞","讚美","平等"], lines:["你好我也好，","一個人不但要看重自己，","也要懂得欣賞別人。"]},
    {id:93, origId:93, content:"量才適性，終身不憂，取璞守直，終身不悔。", semanticTags:["知足","心情","態度"], lines:["量才適性，終身不憂，","取璞守直，終身不悔。"]},
    {id:94, origId:94, content:"勤能補拙，將嘲笑視同啟發，把諷刺當作激勵。", semanticTags:["轉念","毅力","考驗"], lines:["勤能補拙，","將嘲笑視同啟發，","把諷刺當作激勵。"]},
    {id:95, origId:95, content:"要得別人讚歎，就得先讚歎別人。", semanticTags:["讚美","尊重","態度"], lines:["要得別人讚歎，","就得先讚歎別人。"]},
    {id:96, origId:96, content:"污穢的淤泥裡，也產生清蓮；荊棘叢中，也生百合花。", semanticTags:["光明","考驗","困難"], lines:["污穢的淤泥裡，也產生清蓮；","荊棘叢中，也生百合花。"]},
    {id:97, origId:97, content:"人！不能忘形，更不能忘志。", semanticTags:["自律","堅持","方向"], lines:["人！不能忘形，","更不能忘志。"]},
    {id:98, origId:98, content:"受苦的人，沒有悲觀的權利。", semanticTags:["勇氣","信心","困難"], lines:["受苦的人，","沒有悲觀的權利。"]},
    {id:99, origId:99, content:"做學問要在不疑處有疑；待人要在疑處不疑。", semanticTags:["學習","真誠","包容"], lines:["做學問要在不疑處有疑；","待人要在疑處不疑。"]},
    {id:100, origId:100, content:"受人點水之恩，須當湧泉以報。", semanticTags:["感恩","真誠","惜福"], lines:["受人點水之恩，","須當湧泉以報。"]},
    {id:101, origId:101, content:"有願放在心裡，沒有身體力行，正如耕田而不播種，皆是空過因緣。", semanticTags:["行動","努力","時間","準備"], lines:["有願放在心裡，","沒有身體力行，","正如耕田而不播種，","皆是空過因緣。"]},
    {id:102, origId:102, content:"勿輕言「挫折感」、「無力感」；縱然困難如石，也要鑽過去。", semanticTags:["克服","困難","毅力"], lines:["勿輕言「挫折感」、「無力感」；","縱然困難如石，也要鑽過去。"]},
    {id:103, origId:103, content:"生命之美，莫過於誠。誠為一切善法之源。", semanticTags:["真誠","誠信","心情"], lines:["生命之美，莫過於誠。","誠為一切善法之源。"]},
    {id:104, origId:104, content:"人生之貴，莫過於信。信乃人生立世之本。", semanticTags:["誠信","人格","尊嚴"], lines:["人生之貴，莫過於信。","信乃人生立世之本。"]},
    {id:105, origId:105, content:"精神的病比身體上的病，更危險可怕。", semanticTags:["健康","平靜","轉念"], lines:["精神的病比身體上的病，","更危險可怕。"]},
    {id:106, origId:106, content:"物質往下比；精神、品德、智慧往上比。", semanticTags:["智慧","修養","比較"], lines:["物質往下比；","精神、品德、智慧往上比。"]},
    {id:107, origId:107, content:"人生如果不能忍辱，就無法成就事業、學業、道德。", semanticTags:["處事","事業","成就"], lines:["人生如果不能忍辱，","就無法成就","事業、學業、道德。"]},
    {id:108, origId:108, content:"對人要誠心讚歎，而不是曲意承歡。", semanticTags:["真誠","尊重","讚美"], lines:["對人要誠心讚歎，","而不是曲意承歡。"]},
    {id:109, origId:109, content:"給七分表現的孩子，十二分的讚美。", semanticTags:["讚美","教育","溝通"], lines:["給七分表現的孩子，","十二分的讚美。"]},
    {id:110, origId:110, content:"草的堅強來自於它的無限謙卑、忍耐、柔軟，以及永不休止的生長與抗爭。", semanticTags:["謙虛","態度","克服"], lines:["草的堅強來自於它的","無限謙卑、忍耐、柔軟，","以及永不休止的生長與抗爭。"]},
    {id:111, origId:111, content:"我們最強的對手不一定是別人，而可能是我們自己。", semanticTags:["反省","自律","克服"], lines:["我們最強的對手不一定是別人，","而可能是我們自己。"]},
    {id:112, origId:112, content:"無心去往壞處想，則任何話都是好話。", semanticTags:["轉念","包容","說話"], lines:["無心去往壞處想，","則任何話都是好話。"]},
    {id:113, origId:113, content:"人生如高空走索，應專心一意往前看、向前走；不要回頭空懊惱。", semanticTags:["專注","堅持","方向"], lines:["人生如高空走索，應", "專心一意往前看、向前走；", "不要回頭空懊惱。"]},
    {id:114, origId:114, content:"人生最踏實的事，是今日此時有多少力量就儘快付出，去做利益人群的事，造福社會的工作。", semanticTags:["付出","利益","工作"], lines:["人生最踏實的事，是今日此時", "有多少力量就儘快付出，去做", "利益人群的事，造福社會的工作。"]},
    {id:115, origId:115, content:"想成就事業，就先成就自己的品德，昇華自己的人格。", semanticTags:["事業","成就","人格"], lines:["想成就事業，","就先成就自己的品德，","昇華自己的人格。"]},
    {id:116, origId:116, content:"身體污泥可以用水清除，心靈污泥則須用智慧之水消除。", semanticTags:["智慧","改過","修養"], lines:["身體污泥可以用水清除，","心靈污泥則須用智慧之水消除。"]},
    {id:117, origId:117, content:"犯錯生出懺悔心，才能清淨無煩惱。", semanticTags:["改過","反省","煩惱"], lines:["犯錯生出懺悔心，","才能清淨無煩惱。"]},
    {id:118, origId:118, content:"做該做的事是智慧，做不該做的事是愚痴。", semanticTags:["智慧","自律","選擇"], lines:["做該做的事是智慧，","做不該做的事是愚痴。"]},
    {id:119, origId:119, content:"「誠」即是發自內心的一分自動自發的精神。", semanticTags:["真誠","行動","工作"], lines:["「誠」即是發自內心的","一分自動自發的精神。"]},
    {id:120, origId:120, content:"熱心易發，恆心難持；光說不練，則無法體悟真理、實踐道法。", semanticTags:["堅持","毅力","行動"], lines:["熱心易發，恆心難持；", "光說不練，則無法", "體悟真理、實踐道法。"]},
    {id:121, origId:121, content:"人生的價值在功能，而不是在於形象。形象沒有價值。", semanticTags:["價值","付出","成就"], lines:["人生的價值在功能，", "而不是在於形象。", "形象沒有價值。"]},
    {id:122, origId:122, content:"修養是從日常生活中點點滴滴累積而成。", semanticTags:["修養","時間","自律"], lines:["修養是從日常生活中","點點滴滴累積而成。"]},
    {id:123, origId:123, content:"說人是非，傷人傷己；好話要多說，是非不要提；心若正，則行必端。", semanticTags:["說話","衝突","態度"], lines:["說人是非，傷人傷己；","好話要多說，是非不要提；","心若正，則行必端。"]},
    {id:124, origId:124, content:"恆心就如滴水穿石，再大的困難與阻礙也能衝破。", semanticTags:["毅力","堅持","困難"], lines:["恆心就如滴水穿石，","再大的困難與阻礙也能衝破。"]},
    {id:125, origId:125, content:"做好事不要為求功名，也不是為求功德；要抱持盡本分的心，以至誠無私的心去做善事。", semanticTags:["功德","本份","無私"], lines:["做好事不要為求功名，","也不是為求功德；","要抱持盡本分的心，","以至誠無私的心去做善事。"]},
    {id:126, origId:126, content:"有人就有是非，要將是非當教育，凡事善解。", semanticTags:["教育","包容","衝突"], lines:["有人就有是非，","要將是非當教育，","凡事善解。"]},
    {id:127, origId:127, content:"用智慧探討人生真義，用毅力安排人生時間。", semanticTags:["時間","毅力","專注"], lines:["用智慧探討人生真義，","用毅力安排人生時間。"]},
    {id:128, origId:128, content:"慈悲沒有敵人，智慧不起煩惱；布施的人有福，行善的人快樂。", semanticTags:["智慧","快樂","煩惱"], lines:["慈悲沒有敵人，","智慧不起煩惱；","布施的人有福，","行善的人快樂。"]},
    {id:129, origId:129, content:"布施如播種，以歡善心滋潤種子，才會發芽。", semanticTags:["歡喜","付出","態度"], lines:["布施如播種，","以歡善心滋潤種子，","才會發芽。"]},
    {id:130, origId:130, content:"顧好自己的心念，才能真正愛人。", semanticTags:["自愛","心情","正念"], lines:["顧好自己的心念，","才能真正愛人。"]},
    {id:131, origId:131, content:"彎個腰、伸個手，把別人不要的福撿回來，就是我的。", semanticTags:["謙虛","惜福","行動"], lines:["彎個腰、伸個手，","把別人不要的福","撿回來，就是我的。"]},
    {id:132, origId:132, content:"福人居福地，不是福地福人居。", semanticTags:["修養","善念","幸福"], lines:["福人居福地，", "不是福地福人居。"]},
    {id:133, origId:133, content:"盡多少本分，就得多少本事。", semanticTags:["本份","盡責","責任"], lines:["盡多少本分，","就得多少本事。"]},
    {id:134, origId:134, content:"心若開，運就通；運通，福就來。", semanticTags:["轉念","歡喜","幸福"], lines:["心若開，運就通；","運通，福就來。"]},
    {id:135, origId:135, content:"內能自謙，縮小自己；外能忍讓，成就別人。", semanticTags:["成就","謙虛","禮讓"], lines:["內能自謙，縮小自己；","外能忍讓，成就別人。"]},
    {id:136, origId:136, content:"人善人欺天不欺，人惡人怕天不怕。", semanticTags:["無愧","平靜","做人"], lines:["人善人欺天不欺，","人惡人怕天不怕。"]},
    {id:137, origId:137, content:"任勞容易任怨難，耐勞容易耐煩難。", semanticTags:["修養","包容","抱怨"], lines:["任勞容易任怨難，","耐勞容易耐煩難。"]},
    {id:138, origId:138, content:"滴水成河，粒米成籮；勿輕己靈，勿以善小而不為。", semanticTags:["善念","堅持","努力"], lines:["滴水成河，粒米成籮；","勿輕己靈，勿以善小而不為。"]},
    {id:139, origId:139, content:"播下愛的種子，收穫的是快樂的果實。", semanticTags:["快樂","大愛","愛心"], lines:["播下愛的種子，","收穫的是快樂的果實。"]},
    {id:140, origId:140, content:"與其擔心，不如化做耐心；加上信心，方可成就。", semanticTags:["信心","成就","克服"], lines:["與其擔心，不如化做耐心；","加上信心，方可成就。"]},
    {id:141, origId:141, content:"心正邪魔不侵；自作自受，無可怨之天，無可尤之人。", semanticTags:["反省","平靜","抱怨"], lines:["心正邪魔不侵；自作自受，","無可怨之天，無可尤之人。"]},
    {id:142, origId:142, content:"人往往很容易忘失東西，可是被人說幾句不中聽的話，卻丟不掉也忘不了，耿耿於懷。", semanticTags:["包容","說話","心情"], lines:["人往往很容易忘失東西，","可是被人說幾句不中聽的話，","卻丟不掉也忘不了，耿耿於懷。"]},
    {id:143, origId:143, content:"能幹不幹，不如苦幹實幹。", semanticTags:["行動","盡責","工作"], lines:["能幹不幹，","不如苦幹實幹。"]},
    {id:144, origId:144, content:"父母是堂上活菩薩，是真正能接受扶養，能讓我造福靈感的活佛。", semanticTags:["家庭","孝順","父母"], lines:["父母是堂上活菩薩，","是真正能接受扶養，","能讓我造福靈感的活佛。"]},
    {id:145, origId:145, content:"真正的精進是發懺悔心，勇於改過。", semanticTags:["改過","反省","勇氣"], lines:["真正的精進是","發懺悔心，勇於改過。"]},
    {id:146, origId:146, content:"人生好話要如海綿遇水，牢牢吸住；世間是非要如水泥地般堅固，水過則乾。", semanticTags:["包容","說話","智慧"], lines:["人生好話要如海綿遇水，","牢牢吸住；世間是非要如","水泥地般堅固，水過則乾。"]},
    {id:147, origId:147, content:"努力去愛一個原本怨恨的人，是善待自己。", semanticTags:["原諒","包容","大愛"], lines:["努力去愛一個原本怨恨的人，","是善待自己。"]},
    {id:148, origId:148, content:"歡喜心是良藥，不生氣是消業障。", semanticTags:["歡喜","生氣","健康"], lines:["歡喜心是良藥，","不生氣是消業障。"]},
    {id:149, origId:149, content:"有智慧者，不見人過，但見己非。", semanticTags:["智慧","反省","包容"], lines:["有智慧者，","不見人過，","但見己非。"]},
    {id:150, origId:150, content:"凡事都是從智慧學習中得來的。", semanticTags:["智慧","學習","經驗"], lines:["凡事都是從智慧","學習中得來的。"]},
    {id:151, origId:151, content:"小事不做，大事難成。", semanticTags:["本份","行動","成就"], lines:["小事不做，","大事難成。"]},
    {id:152, origId:152, content:"天上最美是星星，人間最美是溫情。", semanticTags:["溫暖","感情","幸福"], lines:["天上最美是星星，", "人間最美是溫情。"]},
    {id:153, origId:153, content:"智慧當向恭敬中求，當向謙卑中求，當向無私中求。", semanticTags:["智慧","謙虛","無私"], lines:["智慧當向恭敬中求，","當向謙卑中求，","當向無私中求。"]},
    {id:154, origId:154, content:"君子如水，隨方就圓，無處不自在。", semanticTags:["修養","處事","包容"], lines:["君子如水，","隨方就圓，","無處不自在。"]},
    {id:155, origId:155, content:"稻穗結得越飽滿，越會往下垂；一個人越有成就，就要越有謙沖的胸襟。", semanticTags:["成就","謙虛","修養"], lines:["稻穗結得越飽滿，","越會往下垂；","一個人越有成就，","就要越有謙沖的胸襟。"]},
    {id:156, origId:156, content:"「願」是成功的起點，人生最需要的就是「願」，也即是希望。", semanticTags:["成就","信心","希望"], lines:["「願」是成功的起點，","人生最需要的就是「願」，","也即是希望。"]},
    {id:157, origId:157, content:"站在半路，比走到目標更辛苦。", semanticTags:["堅持","毅力","方向"], lines:["站在半路，","比走到目標更辛苦。"]},
    {id:158, origId:158, content:"理直氣壯，得理不饒人，不僅惹是生非，傷人傷己，甚至永遠無法化解仇恨，圓融人事。", semanticTags:["包容","修養","原諒","處事","衝突"], lines:["理直氣壯，得理不饒人，","不僅惹是生非，傷人傷己，","甚至永遠無法化解仇恨，圓融人事。"]},
    {id:159, origId:159, content:"職業易生比較心，事業易生功利心。而志業是啟發人人本具的愛心、良知，使人無所求的付出。", semanticTags:["付出","愛心","比較"], lines:["職業易生比較心，事業易生功利心。","而志業是啟發人人本具的","愛心、良知，使人無所求的付出。"]},
    {id:160, origId:160, content:"服務人群是造福，從中學習是修慧；想造福修慧必須身體力行，才能有所收穫。", semanticTags:["學習", "智慧", "付出", "行動", "利益"], lines:["服務人群是造福，","從中學習是修慧；","想造福修慧必須身體力行，","才能有所收穫。"]},
    {id:161, origId:161, content:"最敏感的佛在心中，最有利的菩薩是我們的手和腳；付出我們的力量，做利益眾生的事。", semanticTags:["付出", "利益", "合作"], lines:["最敏感的佛在心中，","最有利的菩薩是我們的手和腳；","付出我們的力量，","做利益眾生的事。"]},
    {id:162, origId:162, content:"心量大，才能付出關心與愛給天下眾生。", semanticTags:["付出","包容","關懷"], lines:["心量大，才能付出","關心與愛給天下眾生。"]},
    {id:163, origId:163, content:"一滴水要想不乾，就設法投入浩渺的大海。", semanticTags:["大愛","團結","團隊"], lines:["一滴水要想不乾，","就設法投入浩渺的大海。"]},
    {id:164, origId:164, content:"行為言語，顯現精神文化的內涵；培養寬大的心量，心量大才能發揮大愛，能原諒別人就是最有福的人。", semanticTags:["大愛","原諒","態度"], lines:["行為言語，顯現精神文化的","內涵；培養寬大的心量，","心量大才能發揮大愛，","能原諒別人就是最有福的人。"]},
    {id:165, origId:165, content:"修行要繫緣修心，藉事練心，隨處養心。", semanticTags:["心情","平靜","修養"], lines:["修行要","繫緣修心，","藉事練心，","隨處養心。"]},
    {id:166, origId:166, content:"人生的地位和名利都是虛假的，最重要的就是要有健康的身體。", semanticTags:["名利","健康","自由"], lines:["人生的地位和名利都是虛假的，","最重要的就是要有健康的身體。"]},
    {id:167, origId:167, content:"命要自己用堅定的願心和恆心去轉化。", semanticTags:["堅持","轉念","命運"], lines:["命要自己用堅定的","願心和恆心去轉化。"]},
    {id:168, origId:168, content:"只要腳踏實地，循序漸進的努力才能有收穫；絕不能妄想一步登天。", semanticTags:["努力","堅持","工作"], lines:["只要腳踏實地，","循序漸進的努力才能有收穫；","絕不能妄想一步登天。"]},
    {id:169, origId:169, content:"有時當思無時苦，好天要積雨來糧。", semanticTags:["惜福","謹慎","準備"], lines:["有時當思無時苦，","好天要積雨來糧。"]},
    {id:170, origId:170, content:"好事要提得起，是非要放得下，成就別人即是成就自己。", semanticTags:["解脫","成就","態度"], lines:["好事要提得起，","是非要放得下，","成就別人即是成就自己。"]},
    {id:171, origId:171, content:"說人是非者，必是是非人；身處團體中，應多去發現別人的優點。", semanticTags:["讚美","團隊","說話"], lines:["說人是非者，","必是是非人；","身處團體中，","應多去發現別人的優點。"]},
    {id:172, origId:172, content:"虛空有盡，我願無窮，發願容易行願難。", semanticTags:["行動","堅持","努力"], lines:["虛空有盡，我願無窮，","發願容易行願難。"]},
    {id:173, origId:173, content:"有多少力量就做多少事，不要心存等待，等待才會落空。", semanticTags:["本份","工作","積極"], lines:["有多少力量就做多少事，","不要心存等待，","等待才會落空。"]},
    {id:174, origId:174, content:"別人無心的一句話，不要有心的放在心裡。", semanticTags:["包容","說話","體諒"], lines:["別人無心的一句話，","不要有心的放在心裡。"]},
    {id:175, origId:175, content:"別人罵我、不諒解我，我反而要感謝他們給我修行的境界。", semanticTags:["感恩","轉念","包容"], lines:["別人罵我、不諒解我，","我反而要感謝他們","給我修行的境界。"]},
    {id:176, origId:176, content:"人往往不是沒有力量去做事；而是不肯去做。", semanticTags:["信心","行動","工作"], lines:["人往往不是沒有力量去做事；","而是不肯去做。"]},
    {id:177, origId:177, content:"人都以為「我」很大，其實他的人往往最狹窄。", semanticTags:["謙虛","包容","反省"], lines:["人都以為「我」很大，","其實他的人往往最狹窄。"]},
    {id:178, origId:178, content:"不要把能行善的身體，用在吃喝玩樂上，應該身行好事。", semanticTags:["行動","健康","本份"], lines:["不要把能行善的身體，","用在吃喝玩樂上，","應該身行好事。"]},
    {id:179, origId:179, content:"不要把能說話的嘴巴用在搬弄是非上，要口說好話。", semanticTags:["說話","讚美","謹慎"], lines:["不要把能說話的嘴巴","用在搬弄是非上，","要口說好話。"]},
    {id:180, origId:180, content:"人人如果都能除去自私與小我，自然就會擴大心胸，培養出誠與正，大公無私的心態。", semanticTags:["包容","大愛","無私","修養"], lines:["人人如果都能除去自私與小我，","自然就會擴大心胸，","培養出誠與正，","大公無私的心態。"]},
    {id:181, origId:181, content:"「慈」是一種最清淨的智慧所發揮出來的功用。", semanticTags:["平靜","智慧","大愛"], lines:["「慈」是一種最清淨的","智慧所發揮出來的功用。"]},
    {id:182, origId:182, content:"每個人心裡都有一股清流，都有一塊福田，隱藏著豐沛的泉源。", semanticTags:["善念","平靜","心情"], lines:["每個人心裡都有一股清流，","都有一塊福田，","隱藏著豐沛的泉源。"]},
    {id:183, origId:183, content:"人生多一分感恩，就多一分美化。", semanticTags:["感恩","知足","歡喜"], lines:["人生多一分感恩，","就多一分美化。"]},
    {id:184, origId:184, content:"一個不能緩和憤怒之火的人，會喪失他所有的名譽。", semanticTags:["生氣","自律","態度"], lines:["一個不能緩和憤怒之火的人，","會喪失他所有的名譽。"]},
    {id:185, origId:185, content:"要用心、細心，不要操心、煩心。", semanticTags:["專注","平靜","心情"], lines:["要用心、細心，","不要操心、煩心。"]},
    {id:186, origId:186, content:"每一天都是做人的開始，每一個時刻都是自己的警惕。", semanticTags:["做人","反省","謹慎"], lines:["每一天都是做人的開始，","每一個時刻都是自己的警惕。"]},
    {id:187, origId:187, content:"時間對一個有智慧的人來說，就如鑽石般的珍貴；對愚人來說，卻像泥土，一點也沒有價值。", semanticTags:["智慧","時間","專注"], lines:["時間對一個有智慧的人來說，","就如鑽石般的珍貴；","對愚人來說，卻像泥土，","一點也沒有價值。"]},
    {id:188, origId:188, content:"為自己找藉口逃避的人，永遠不會進步。", semanticTags:["改過","自律","反省"], lines:["為自己找藉口逃避的人，","永遠不會進步。"]},
    {id:189, origId:189, content:"心中常存善念；遇事逢凶化吉。", semanticTags:["善念","轉念","樂觀"], lines:["心中常存善念；","遇事逢凶化吉。"]},
    {id:190, origId:190, content:"不要怕人家說你傻，要擔心人家說你太聰明，太聰明就是狡猾。", semanticTags:["真誠","謙虛","本份"], lines:["不要怕人家說你傻，","要擔心人家說你太聰明，","太聰明就是狡猾。"]},
    {id:191, origId:191, content:"人不能忘形，更不能喪志；寧願被毀滅，不願被擊敗。", semanticTags:["勇氣","克服","失敗"], lines:["人不能忘形，更不能喪志；","寧願被毀滅，不願被擊敗。"]},
    {id:192, origId:192, content:"為人處事要小心，但不要小心眼。", semanticTags:["謹慎","包容","處事"], lines:["為人處事要小心，","但不要小心眼。"]},
    {id:193, origId:193, content:"人多力大，福就大。", semanticTags:["團隊", "團結", "合作"], lines:["人多力大，","福就大。"]},
    {id:194, origId:194, content:"凡事善解，能忍自安。", semanticTags:["平靜","安定","轉念"], lines:["凡事善解，","能忍自安。"]},
    {id:195, origId:195, content:"哭泣不能消除昨日的哀傷，只能消減明日的銳氣。", semanticTags:["轉念","勇氣","樂觀"], lines:["哭泣不能消除昨日的哀傷，","只能消減明日的銳氣。"]},
    {id:196, origId:196, content:"君子立恆志，小人恆立志。", semanticTags:["堅持","方向","毅力"], lines:["君子立恆志，","小人恆立志。"]},
    {id:197, origId:197, content:"順境的美德是節制；逆境的美德是忍耐。", semanticTags:["自律","考驗","修養"], lines:["順境的美德是節制；","逆境的美德是忍耐。"]},
    {id:198, origId:198, content:"人真正的財富在行善。", semanticTags:["付出","功德","善念"], lines:["人真正的財富在行善。"]},
    {id:199, origId:199, content:"靜坐常思己過，閒談莫論人非。", semanticTags:["反省","說話","修養"], lines:["靜坐常思己過，","閒談莫論人非。"]},
    {id:200, origId:200, content:"並非有錢就快樂，問心無愧最心安。", semanticTags:["快樂","無愧","安定"], lines:["並非有錢就快樂，","問心無愧最心安。"]},
    {id:201, origId:201, content:"欣賞別人就是莊嚴自己。", semanticTags:["欣賞","尊重","謙虛"], lines:["欣賞別人就是莊嚴自己。"]},
    {id:202, origId:202, content:"成功是優點的發揮，失敗是缺點的累積。", semanticTags:["失敗","成就","反省"], lines:["成功是優點的發揮，","失敗是缺點的累積。"]},
    {id:203, origId:203, content:"心美，看什麼都順眼。", semanticTags:["轉念","歡喜","心情"], lines:["心美，","看什麼都順眼。"]},
    {id:204, origId:204, content:"要批評別人時，先想想自己是否完美無缺。", semanticTags:["批評","反省","謙虛"], lines:["要批評別人時，","先想想自己是否完美無缺。"]},
    {id:205, origId:205, content:"犯錯生出懺悔心，才能清淨無煩惱。", semanticTags:["改過","反省","煩惱"], lines:["犯錯生出懺悔心，","才能清淨無煩惱。"]},
    {id:206, origId:206, content:"抱著盡本分的心去做好事，才是真正的好事，才是至誠無私的善事。", semanticTags:["本份","真誠","付出","無私"], lines:["抱著盡本分的心去做好事，","才是真正的好事，","才是至誠無私的善事。"]},
    {id:207, origId:207, content:"自造福田，自得福緣。", semanticTags:["付出","行動","功德"], lines:["自造福田，","自得福緣。"]},
    {id:208, origId:208, content:"人生要為善競爭，分秒必爭。", semanticTags:["時間","積極","善念"], lines:["人生要為善競爭，","分秒必爭。"]},
    {id:209, origId:209, content:"有人扯後腿，要心存感恩；沒有人扯，就練不出腿勁。", semanticTags:["感恩","轉念","考驗"], lines:["有人扯後腿，要心存感恩；", "沒有人扯，就練不出腿勁。"]},
    {id:210, origId:210, content:"要適應他人，不要要求他人。", semanticTags:["包容","體諒","處事"], lines:["要適應他人，","不要要求他人。"]},
    {id:211, origId:211, content:"不怕事多，只怕多事。", semanticTags:["本份","工作","說話"], lines:["不怕事多，","只怕多事。"]},
    {id:212, origId:212, content:"別人因為「沒有」才要佔我便宜，我因為「有」才有便宜讓人家佔。", semanticTags:["包容","知足","付出"], lines:["別人因為「沒有」才要佔我便宜，","我因為「有」才有便宜讓人家佔。"]},
    {id:213, origId:213, content:"要改變別人先改變自己，因為要求自己比要求別人容易。", semanticTags:["自律","轉念","改變"], lines:["要改變別人先改變自己，","因為要求自己比要求別人容易。"]},
    {id:214, origId:214, content:"每天無所事事，是人生的消費者；積極有用才是人生的創造者。", semanticTags:["時間","本份","工作"], lines:["每天無所事事，","是人生的消費者；","積極有用才是","人生的創造者。"]},
    {id:215, origId:215, content:"有人點燈求光明，其實真正的光明在我們的心裡；佛前的燈不要刻意去點，要緊的是點燃我們的心燈。", semanticTags:["智慧","心情","光明"], lines:["有人點燈求光明，其實","真正的光明在我們的心裡；","佛前的燈不要刻意去點，","要緊的是點燃我們的心燈。"]},
    {id:216, origId:216, content:"不想過去，放棄雜念；不想未來，放棄妄念；把握當下，並提引正念。", semanticTags:["正念","平靜","安定"], lines:["不想過去，放棄雜念；","不想未來，放棄妄念；","把握當下，並提引正念。"]},
    {id:217, origId:217, content:"做好事不是有錢人的專利，而是有心人的參與。", semanticTags:["付出","行動","平等"], lines:["做好事不是有錢人的專利，","而是有心人的參與。"]},
    {id:218, origId:218, content:"種如是因，結如是緣，得如是果。", semanticTags:["選擇","改過","經驗"], lines:["種如是因，","結如是緣，","得如是果。"]},
    {id:219, origId:219, content:"多一分踏實，少一分空虛；多一分清淨，少一分煩惱。", semanticTags:["平靜","煩惱","工作"], lines:["多一分踏實，","少一分空虛；","多一分清淨，","少一分煩惱。"]},
    {id:220, origId:220, content:"再不愛吃的東西也要吃完，再不愛聽的話也要聽完。", semanticTags:["包容","惜福","修養"], lines:["再不愛吃的東西也要吃完，","再不愛聽的話也要聽完。"]},
    {id:221, origId:221, content:"忘功不忘過，忘怨不忘恩。", semanticTags:["感恩","謙虛","改過"], lines:["忘功不忘過，","忘怨不忘恩。"]},
    {id:222, origId:222, content:"臨事須替別人想，論人先向自己想。", semanticTags:["包容","反省","體諒"], lines:["臨事須替別人想，","論人先向自己想。"]},
    {id:223, origId:223, content:"白紙黑字唸再多，不如身體力行做一遍。", semanticTags:["行動","努力","工作","學習"], lines:["白紙黑字唸再多，","不如身體力行做一遍。"]},
    {id:224, origId:224, content:"君子如水，隨方就圓，無處不自在。", semanticTags:["修養","處事","包容"], lines:["君子如水，","隨方就圓，","無處不自在。"]},
    {id:225, origId:225, content:"少年要求好學業，青年要求好職業；但人的一生不能沒有「好志業、好道業、好德業」。", semanticTags:["學習","工作","方向"], lines:["少年要求好學業，","青年要求好職業；","但人的一生不能沒有","「好志業、好道業、好德業」。"]},
    {id:226, origId:226, content:"寧做一個「盡力做事而被批評的人」，也不要做一個「不做事，只會批評的人」。", semanticTags:["批評","盡責","工作"], lines:["寧做一個","「盡力做事而被批評的人」，","也不要做一個","「不做事，只會批評的人」。"]},
    {id:227, origId:227, content:"用菩薩的智慧，教育我們的孩子；用媽媽的愛心，愛我們的學生。", semanticTags:["智慧","教育","愛心","父母","孝順"], lines:["用菩薩的智慧，","教育我們的孩子；","用媽媽的愛心，","愛我們的學生。"]},
    {id:228, origId:228, content:"「得」的後面是「失」，「利」的後面是「害」。", semanticTags:["得失","名利","解脫"], lines:["「得」的後面是「失」，","「利」的後面是「害」。"]},
    {id:229, origId:229, content:"物質慾望往下比，精神道德往上比。", semanticTags:["欲望","知足","修養"], lines:["物質慾望往下比，","精神道德往上比。"]},
    {id:230, origId:230, content:"手心向下是助人，手心向上是求人；助人快樂，求人痛苦。", semanticTags:["快樂","付出","合作"], lines:["手心向下是助人，","手心向上是求人；","助人快樂，求人痛苦。"]},
    {id:231, origId:231, content:"樹大會招風，要時時修剪。", semanticTags:["謙虛","自律","反省"], lines:["樹大會招風，","要時時修剪。"]},
    {id:232, origId:232, content:"凡夫有兩個大煩惱：做好事怕別人不知道；做壞事怕別人知道。", semanticTags:["煩惱","反省","無愧"], lines:["凡夫有兩個大煩惱：","做好事怕別人不知道；","做壞事怕別人知道。"]},
    {id:233, origId:233, content:"菩薩有隱惡揚善的美德，凡夫有妒賢嫉能的心理。", semanticTags:["包容","修養","讚美"], lines:["菩薩有隱惡揚善的美德，","凡夫有妒賢嫉能的心理。"]},
    {id:234, origId:234, content:"多一分善念，少一個惡念；多一分良知，少一個痴迷。", semanticTags:["善念","自律","正念"], lines:["多一分善念，少一個惡念；","多一分良知，少一個痴迷。"]},
    {id:235, origId:235, content:"邀功令人討厭，諉過令人痛恨。", semanticTags:["盡責","謙虛","誠信"], lines:["邀功令人討厭，","諉過令人痛恨。"]},
    {id:236, origId:236, content:"對別人不要計較，對自己要好好檢討。", semanticTags:["反省","包容","處事"], lines:["對別人不要計較，","對自己要好好檢討。"]},
    {id:237, origId:237, content:"看別人不順眼，是自己修養不夠。", semanticTags:["修養","轉念","反省"], lines:["看別人不順眼，","是自己修養不夠。"]},
    {id:238, origId:238, content:"能忍而不計較，則再大的困難也能克服。", semanticTags:["克服","困難","包容"], lines:["能忍而不計較，","則再大的困難也能克服。"]},
    {id:239, origId:239, content:"自己害自己，莫過於亂發脾氣。", semanticTags:["生氣","自律","反省"], lines:["自己害自己，","莫過於亂發脾氣。"]},
    {id:240, origId:240, content:"無求品自高，無欲則剛。", semanticTags:["知足","欲望","解脫"], lines:["無求品自高，","無欲則剛。"]},
    {id:241, origId:241, content:"地上種了菜，就不易長草；心中有善，就不易生惡。", semanticTags:["善念","修養","心情"], lines:["地上種了菜，就不易長草；","心中有善，就不易生惡。"]},
    {id:242, origId:242, content:"起步了就要往前走，不怕慢，只怕站。", semanticTags:["堅持","行動","方向"], lines:["起步了就要往前走，","不怕慢，只怕站。"]},
    {id:243, origId:243, content:"一個缺口的杯子，如果換一個角度看它，它仍然是圓的。", semanticTags:["轉念","包容","樂觀"], lines:["一個缺口的杯子，","如果換一個角度看它，","它仍然是圓的。"]},
    {id:244, origId:244, content:"心中有愛，白雪都溶化；大家有愛，黑暗變光明。", semanticTags:["大愛","光明","團結"], lines:["心中有愛，白雪都溶化；","大家有愛，黑暗變光明。"]},
    {id:245, origId:245, content:"寧靜最美，安定最樂。", semanticTags:["安定","平靜","快樂"], lines:["寧靜最美，","安定最樂。"]},
    {id:246, origId:246, content:"以修行的心境，累積遇境，自轉智慧。", semanticTags:["智慧","轉念","考驗"], lines:["以修行的心境，","累積遇境，自轉智慧。"]},
    {id:247, origId:247, content:"環境的髒亂不可怕，最可怕的是任由心地屯積塵埃，而不知清除汙垢，去除惡習。", semanticTags:["反省","改過","自律"], lines:["環境的髒亂不可怕，","最可怕的是任由心地屯積塵埃，","而不知清除汙垢，去除惡習。"]},
    {id:248, origId:248, content:"不要把陰影覆藏在心裡，要散發光和熱，生命才有意義。", semanticTags:["解脫","轉念","光明"], lines:["不要把陰影覆藏在心裡，","要散發光和熱，","生命才有意義。"]},
    {id:249, origId:249, content:"把慈悲形象化，付諸於具體的行動中。", semanticTags:["行動","大愛","付出"], lines:["把慈悲形象化，","付諸於具體的行動中。"]},
    {id:250, origId:250, content:"不要總是要求別人給我什麼，要想我能為別人做什麼。", semanticTags:["付出","大愛","處事"], lines:["不要總是要求別人給我什麼，","要想我能為別人做什麼。"]},
    {id:251, origId:251, content:"凡夫只看到別人外在的汙點，卻看不到自己內心的垃圾。", semanticTags:["反省","改過","謙虛"], lines:["凡夫只看到別人外在的汙點，","卻看不到自己內心的垃圾。"]},
    {id:252, origId:252, content:"要從聲色調習自己的一舉一動，任何時候都要和顏悅色，柔聲細語。", semanticTags:["修養","態度","說話"], lines:["要從聲色調習自己的一舉一動，","任何時候都要和顏悅色，柔聲細語。"]},
    {id:253, origId:253, content:"人生不一定球球是好球，但是有歷練的強打者，隨時都可以揮棒。", semanticTags:["考驗","勇氣","積極"], lines:["人生不一定球球是好球，","但是有歷練的強打者，","隨時都可以揮棒。"]},
    {id:254, origId:254, content:"佛心看人，人人是佛。", semanticTags:["平等","尊重","包容"], lines:["佛心看人，","人人是佛。"]},
    {id:255, origId:255, content:"逆境，是非來源，心中要持一寬字。", semanticTags:["包容","轉念","處事"], lines:["逆境，是非來源，","心中要持一寬字。"]},
    {id:256, origId:256, content:"人生都是向外求，其實最重要的是內心的追求。", semanticTags:["平靜","反省","心情"], lines:["人生都是向外求，","其實最重要的是內心的追求。"]},
    {id:257, origId:257, content:"生命無常，慧命永存；愛心無涯，精神常在。", semanticTags:["愛心","珍惜","生命"], lines:["生命無常，慧命永存；", "愛心無涯，精神常在。"]},
    {id:258, origId:258, content:"人生沒有所有權，只有生命的使用權。", semanticTags:["時間","珍惜","生命"], lines:["人生沒有所有權，","只有生命的使用權。"]},
    {id:259, origId:259, content:"開口傷神氣，舌動惹是非。", semanticTags:["說話","修養","謹慎"], lines:["開口傷神氣，","舌動惹是非。"]},
    {id:260, origId:260, content:"心安茅屋穩，心定菜根香。", semanticTags:["平靜","知足","安定"], lines:["心安茅屋穩，","心定菜根香。"]},
    {id:261, origId:261, content:"縮小自己，反求諸己，包容別人。", semanticTags:["包容","謙虛","反省"], lines:["縮小自己，","反求諸己，","包容別人。"]},
    {id:262, origId:262, content:"在順境時，要使生活有風采；逆境時，要不散亂，保持靜心。", semanticTags:["平靜","自律","考驗"], lines:["在順境時，要使生活有風采；","逆境時，要不散亂，保持靜心。"]},
    {id:263, origId:263, content:"今天的工作，將是明天的文章，後天的歷史。", semanticTags:["盡責","工作","時間"], lines:["今天的工作，將是","明天的文章，","後天的歷史。"]},
    {id:264, origId:264, content:"每天都是生命中的一張白紙；每一個人、每一件事，都是我們的一篇文章。", semanticTags:["學習","珍惜","時間"], lines:["每天都是生命中的一張白紙；", "每一個人、每一件事，", "都是我們的一篇文章。"]},
    {id:265, origId:265, content:"心中常存善解、包容、感恩、知足、惜福。", semanticTags:["包容","知足","感恩"], lines:["心中常存善解、包容、","感恩、知足、惜福。"]},
    {id:266, origId:266, content:"心中有愛，有善念，而能身體力行者，即是菩薩。", semanticTags:["善念","行動","愛心"], lines:["心中有愛，有善念，","而能身體力行者，即是菩薩。"]},
    {id:267, origId:267, content:"世間如烘樓，要禁得起鍛鍊，才能將百鍊鋼化為繞指柔。", semanticTags:["考驗","磨練","堅持"], lines:["世間如烘樓，要禁得起鍛鍊，","才能將百鍊鋼化為繞指柔。"]},
    {id:268, origId:268, content:"真正的智慧是要保持謙虛的態度，有智慧才能明辨是非、善惡，有謙虛才能建立美滿人生。", semanticTags:["智慧","謙虛","態度"], lines:["真正的智慧是要","保持謙虛的態度，","有智慧才能明辨是非、善惡，","有謙虛才能建立美滿人生。"]},
    {id:269, origId:269, content:"善用時間者，就能成就事功。", semanticTags:["時間","成就","專注"], lines:["善用時間者，","就能成就事功。"]},
    {id:270, origId:270, content:"行為言語顯現精神文化的內涵。培養寬大的心量，才能發揮大愛。", semanticTags:["大愛","修養","包容","態度"], lines:["行為言語顯現精神文化的內涵。","培養寬大的心量，才能發揮大愛。"]},
    {id:271, origId:271, content:"做好事是本分事，並不是為求名，也不是為求利。", semanticTags:["本份","名利","付出"], lines:["做好事是本分事，","並不是為求名，","也不是為求利。"]},
    {id:272, origId:272, content:"人生的行為繫乎觀念；觀念正確，人生道路的方向就不會偏差。", semanticTags:["方向","選擇","正念"], lines:["人生的行為繫乎觀念；","觀念正確，人生道路的","方向就不會偏差。"]},
    {id:273, origId:273, content:"得人尊重，必先自我尊重，啟發自我良知，發揮在人生最需要的地方。", semanticTags:["尊嚴","自愛","人格","做人"], lines:["得人尊重，必先自我尊重，","啟發自我良知，發揮在","人生最需要的地方。"]},
    {id:274, origId:274, content:"智慧是從生活人事的磨練而得來。", semanticTags:["智慧","考驗","經驗"], lines:["智慧是從生活人事的","磨練而得來。"]},
    {id:275, origId:275, content:"人之大患在於自以為是，自以為了不起，甚至自我膨脹。", semanticTags:["謙虛","反省","修養"], lines:["人之大患在於","自以為是，","自以為了不起，","甚至自我膨脹。"]},
    {id:276, origId:276, content:"愚痴者，常在心地築起堅固之牆，禁錮自己；智慧者，卻能拆掉這堵牆，解放裡面的人。", semanticTags:["智慧","解脫","自由","轉念"], lines:["愚痴者，常在心地築起","堅固之牆，禁錮自己；","智慧者，卻能拆掉","這堵牆，解放裡面的人。"]},
    {id:277, origId:277, content:"謊言像一朵盛開的鮮花，外表美麗，生命短暫。", semanticTags:["誠信","真誠","說話"], lines:["謊言像一朵盛開的鮮花，","外表美麗，生命短暫。"]},
    {id:278, origId:278, content:"從感恩、善解中，可以學習到愛的真諦。", semanticTags:["感恩","學習","愛心"], lines:["從感恩、善解中，","可以學習到愛的真諦。"]},
    {id:279, origId:279, content:"控制不了自己的情緒，而大發脾氣，和精神病的差別，只在發作時間的長短而已。", semanticTags:["時間","生氣","自律"], lines:["控制不了自己的情緒，","而大發脾氣，","和精神病的差別，","只在發作時間的長短而已。"]},
    {id:280, origId:280, content:"得先調整自己的腳步，做好自己的本分事，有端正誠懇的形象，才能真正以身、行去影響他人。", semanticTags:["本份","自律","盡責","做人"], lines:["得先調整自己的腳步，","做好自己的本分事，","有端正誠懇的形象，","才能真正以身、行去影響他人。"]},
    {id:281, origId:281, content:"不要隨心所欲，要隨心教育自己。", semanticTags:["教育","自律","改過"], lines:["不要隨心所欲，","要隨心教育自己。"]},
    {id:282, origId:282, content:"面對惡言惡語，也是一種修行。", semanticTags:["包容","修養","說話"], lines:["面對惡言惡語，","也是一種修行。"]},
    {id:283, origId:283, content:"人間壽命因為短暫，才更顯得珍貴。", semanticTags:["時間","珍惜","生命"], lines:["人間壽命因為短暫，","才更顯得珍貴。"]},
    {id:284, origId:284, content:"聰明的人得失心重；有智慧的人勇於捨得。", semanticTags:["智慧","得失","解脫"], lines:["聰明的人得失心重；","有智慧的人勇於捨得。"]},
    {id:285, origId:285, content:"看淡自己是般若，看重自己是執著。", semanticTags:["解脫","反省","謙虛"], lines:["看淡自己是般若，","看重自己是執著。"]},
    {id:286, origId:286, content:"能受天魔是鐵漢；不遭人妒是庸才。", semanticTags:["毅力","考驗","堅持"], lines:["能受天魔是鐵漢；","不遭人妒是庸才。"]},
    {id:287, origId:287, content:"只有在平心靜氣的時候，才會比較容易發現自己的缺點。", semanticTags:["平靜","反省","改過"], lines:["只有在平心靜氣的時候，","才會比較容易發現自己的缺點。"]},
    {id:288, origId:288, content:"寧靜致遠，淡泊明志。", semanticTags:["平靜","知足","方向"], lines:["寧靜致遠，","淡泊明志。"]},
    {id:289, origId:289, content:"步行在人生的道路上，若能用心看路，便知每一步程皆是「道」。", semanticTags:["專注","選擇","經驗"], lines:["步行在人生的道路上，","若能用心看路，","便知每一步程皆是「道」。"]},
    {id:290, origId:290, content:"調服自己的心，要順境依勢，不能一味地嚴管強求，也不能完全放肆，任由他去。", semanticTags:["自律","平靜","心情"], lines:["調服自己的心，要順境依勢，","不能一味地嚴管強求，","也不能完全放肆，任由他去。"]},
    {id:291, origId:291, content:"身是菩提樹，心如明鏡台，時時勤拂拭，勿使惹塵埃。", semanticTags:["自律","反省","平靜"], lines:["身是菩提樹，心如明鏡台，","時時勤拂拭，勿使惹塵埃。"]},
    {id:292, origId:292, content:"事是從心做，念是從心起，報也會從心得。", semanticTags:["工作","心情","選擇"], lines:["事是從心做，","念是從心起，","報也會從心得。"]},
    {id:293, origId:293, content:"我們若能時時照顧好自心，行為必定端正，所言所行必能利益人群。", semanticTags:["利益","行動","態度"], lines:["我們若能時時照顧好自心，","行為必定端正，","所言所行必能利益人群。"]},
    {id:294, origId:294, content:"人生世間，最苦的莫過於心病，病在不知足，在相互比較，在不知「人外有人，天外有天」，須知不滿足的心是最痛苦的心。", semanticTags:["知足","比較","修養"], lines:["人生世間，最苦的莫過於心病，","病在不知足，在相互比較，","在不知「人外有人，天外有天」，","須知不滿足的心是最痛苦的心。"]},
    {id:295, origId:295, content:"能知足就能常樂，能感恩就能惜福。", semanticTags:["知足","感恩","惜福"], lines:["能知足就能常樂，","能感恩就能惜福。"]},
    {id:296, origId:296, content:"人應互相勉勵，互相關懷，彼此提醒。那怕舉手投足，開口動念，都要時刻謹慎，勿讓心念偏差，導致行為乖繆。", semanticTags:["謹慎","自律","關懷","修養"], lines:["人應互相勉勵，互相關懷，","彼此提醒。那怕舉手投足，","開口動念，都要時刻謹慎，","勿讓心念偏差，導致行為乖繆。"]},
    {id:297, origId:297, content:"人若常存善解心，便可結歡喜緣，生歡喜心；縱使極複雜的煩惱，亦能從善解中斷除。", semanticTags:["歡喜","煩惱","轉念"], lines:["人若常存善解心，","便可結歡喜緣，生歡喜心；","縱使極複雜的煩惱，","亦能從善解中斷除。"]},
    {id:298, origId:298, content:"煩惱由心生，有時僅是一個笑容或一句良語，即能化解衝突，避免彼此的煩惱。", semanticTags:["煩惱","溝通","衝突"], lines:["煩惱由心生，有時僅是","一個笑容或一句良語，","即能化解衝突，避免彼此的煩惱。"]},
    {id:299, origId:299, content:"好善的人，不是短時的行善；偏惡的人，也不是現前一念。向善向惡是長期深藏在內心的觀念。", semanticTags:["堅持","善念","修養"], lines:["好善的人，不是短時的行善；","偏惡的人，也不是現前一念。","向善向惡是長期深藏在內心的觀念。"]},
    {id:300, origId:300, content:"真正的幸福是無所求而為，是付出之後的感覺。", semanticTags:["付出","歡喜","幸福"], lines:["真正的幸福是無所求而為，","是付出之後的感覺。"]},
    {id:301, origId:301, content:"心靈的和平，須從教育開始；人受了教育才知道愛和福，才懂得發揮人生最寶貴的功能。", semanticTags:["教育","平靜","態度","愛心"], lines:["心靈的和平，須從教育開始；","人受了教育才知道愛和福，","才懂得發揮人生最寶貴的功能。"]},
    {id:302, origId:302, content:"愛就要付出去造福，智慧就要用心去教育。", semanticTags:["智慧","教育","付出"], lines:["愛就要付出去造福，","智慧就要用心去教育。"]},
    {id:303, origId:303, content:"付出後看到成就的歡喜心叫智慧。", semanticTags:["智慧","歡喜","付出"], lines:["付出後看到成就的","歡喜心叫智慧。"]},
    {id:304, origId:304, content:"莫道人身容易得，電光石火剎那間。", semanticTags:["時間","珍惜","生命"], lines:["莫道人身容易得，","電光石火剎那間。"]},
    {id:305, origId:305, content:"是非不必爭人我，好歹何須論長短。", semanticTags:["包容","解脫","溝通"], lines:["是非不必爭人我，","好歹何須論長短。"]},
    {id:306, origId:306, content:"悟心容易，息心難息，得心緣到處閒。", semanticTags:["平靜","解脫","心情"], lines:["悟心容易，息心難息，","得心緣到處閒。"]},
    {id:307, origId:307, content:"人無妄念是禪，坐中見性為定。", semanticTags:["平靜","專注","心情"], lines:["人無妄念是禪，","坐中見性為定。"]},
    {id:308, origId:308, content:"手把青秧插滿田，低頭便見水中央，心地清淨方為道，退步原來是向前。", semanticTags:["平靜","謙虛","轉念"], lines:["手把青秧插滿田，","低頭便見水中央，","心地清淨方為道，","退步原來是向前。"]},
    {id:309, origId:309, content:"說錯了話，擋了自己又踢到別人。", semanticTags:["說話","處事","修養"], lines:["說錯了話，","擋了自己又踢到別人。"]},
    {id:310, origId:310, content:"懂理不懂事，能知不能行，此「理」與「知」就如空花水月，要「理事」相應「知行合一」，才是真理與真知。", semanticTags:["行動","努力","工作"], lines:["懂理不懂事，能知不能行，","此「理」與「知」就如空花水月，","要「理事」相應「知行合一」，","才是真理與真知。"]},
    {id:311, origId:311, content:"多為自己祝福就是往好處想；逆境即是增上緣。", semanticTags:["考驗","轉念","感恩"], lines:["多為自己祝福就是往好處想；","逆境即是增上緣。"]},
    {id:312, origId:312, content:"不再自我教育者，才是真正的文盲。", semanticTags:["教育","反省","學習"], lines:["不再自我教育者，","才是真正的文盲。"]},
    {id:313, origId:313, content:"聰明即是耳朵很聰，專聽別人是非；眼睛很明，專看別人缺點。", semanticTags:["反省","說話","處事"], lines:["聰明即是耳朵很聰，","專聽別人是非；","眼睛很明，","專看別人缺點。"]},
    {id:314, origId:314, content:"懺悔是心靈的告白，也可說是精神污染的大掃除。", semanticTags:["改過","反省","真誠"], lines:["懺悔是心靈的告白，","也可說是精神污染的大掃除。"]},
    {id:315, origId:315, content:"做一切好事要把握時機，也要把握因緣，因緣消逝才想做就來不及了。", semanticTags:["機會","時間","行動"], lines:["做一切好事要把握時機，","也要把握因緣，","因緣消逝才想做就來不及了。"]},
    {id:316, origId:316, content:"把他人拿來做自己的鏡子：看他人的優點，自我鞭策；看他人的缺點，反省自己。", semanticTags:["反省","學習","讚美"], lines:["把他人拿來做自己的鏡子：","看他人的優點，自我鞭策；","看他人的缺點，反省自己。"]},
    {id:317, origId:317, content:"恆心就如滴水穿石，再大的困難與阻礙也能衝破。", semanticTags:["毅力","堅持","困難"], lines:["恆心就如滴水穿石，","再大的困難與阻礙也能衝破。"]},
    {id:318, origId:318, content:"心不專，念不一，做事則難以成就。", semanticTags:["成就","專注","工作"], lines:["心不專，念不一，","做事則難以成就。"]},
    {id:319, origId:319, content:"什麼人都可以原諒，唯有不誠實的人不可原諒。", semanticTags:["原諒","誠信","真誠"], lines:["什麼人都可以原諒，","唯有不誠實的人不可原諒。"]},
    {id:320, origId:320, content:"心量狹小則多煩惱，心量廣大則智慧豐饒。", semanticTags:["智慧","煩惱","包容"], lines:["心量狹小則多煩惱，","心量廣大則智慧豐饒。"]},
    {id:321, origId:321, content:"盡責任的人生才有踏實感。", semanticTags:["盡責","本份","責任"], lines:["盡責任的人生才有踏實感。"]},
    {id:322, origId:322, content:"要使人相信你，不在於言詞的巧辯，而在於行為的實踐。", semanticTags:["行動","誠信","真誠"], lines:["要使人相信你，","不在於言詞的巧辯，","而在於行為的實踐。"]},
    {id:323, origId:323, content:"日常生活中，即使幾千萬日的安全，也彌補不了剎那間的疏忽。", semanticTags:["謹慎","專注","時間"], lines:["日常生活中，","即使幾千萬日的安全，","也彌補不了剎那間的疏忽。"]},
    {id:324, origId:324, content:"人的心念意境，如能保持開朗清明，則展現於周遭的環境都是美和善的。", semanticTags:["轉念","善念","心情"], lines:["人的心念意境，如能保持開朗清明，","則展現於周遭的環境都是美和善的。"]},
    {id:325, origId:325, content:"將氣憤的境，轉為柔和的心境，再轉換為友愛，這個世間將愈益完美。", semanticTags:["轉念","愛心","溫暖"], lines:["將氣憤的境，","轉為柔和的心境，","再轉換為友愛，","這個世間將愈益完美。"]},
    {id:326, origId:326, content:"無論環境如何困難，都能保持奮鬥勇氣的人，才能突破困境，掌握有利形勢。", semanticTags:["勇氣","毅力","困難","積極"], lines:["無論環境如何困難，","都能保持奮鬥勇氣的人，","才能突破困境，","掌握有利形勢。"]},
    {id:327, origId:327, content:"煩惱是因別人無心的一句話，自己卻有意的接受。", semanticTags:["煩惱","包容","轉念"], lines:["煩惱是因別人無心的一句話，","自己卻有意的接受。"]},
    {id:328, origId:328, content:"歡喜心是一種涵養，能令周圍的人都有如沐春風的喜悅感。", semanticTags:["歡喜","修養","溫暖"], lines:["歡喜心是一種涵養，","能令周圍的人都有如沐春風的喜悅感。"]},
    {id:329, origId:329, content:"任何挫折困難，對有志學習的人而言，正是磨練的好機會。", semanticTags:["學習","磨練","困難"], lines:["任何挫折困難，","對有志學習的人而言，","正是磨練的好機會。"]},
    {id:330, origId:330, content:"好的領導者，必須心胸開闊，在應對進退中，以知足、感恩、善解、包容看待一人、事、物。", semanticTags:["知足","包容","感恩"], lines:["好的領導者，必須心胸開闊，","在應對進退中，以","知足、感恩、善解、包容","看待一人、事、物。"]},
    {id:331, origId:331, content:"以清淨感恩的心，付出心中的愛，時時長養內心的善念。", semanticTags:["善念","感恩","付出"], lines:["以清淨感恩的心，","付出心中的愛，","時時長養內心的善念。"]},
    {id:332, origId:332, content:"真正的人生要樂中能知苦，在苦中也能體會樂的甘美；不知苦的人，會因對苦難缺乏敏銳的感受力，而變得沒有人情味。", semanticTags:["感恩","困難","幸福"], lines:["真正的人生要樂中能知苦，","在苦中也能體會樂的甘美；","不知苦的人，會因對苦難缺乏","敏銳的感受力，而變得沒有人情味。"]},
    {id:333, origId:333, content:"要做事，不要怕人事，事是人做出來的。", semanticTags:["勇氣","處事","工作"], lines:["要做事，不要怕人事，","事是人做出來的。"]},
    {id:334, origId:334, content:"用有形的教育轉化無形的心念，用無形的精神啟發力量，展現於有形的行動上。", semanticTags:["教育","行動","學習"], lines:["用有形的教育轉化無形的心念，","用無形的精神啟發力量，","展現於有形的行動上。"]},
    {id:335, origId:335, content:"再好的機會福報，如不能把握因緣，一樣會溜走。", semanticTags:["機會","選擇","珍惜"], lines:["再好的機會福報，","如不能把握因緣，","一樣會溜走。"]},
    {id:336, origId:336, content:"遺失現在就會後悔過去。", semanticTags:["珍惜","時間","方向"], lines:["遺失現在就會後悔過去。"]},
    {id:337, origId:337, content:"真正自愛的人，不會與人計較。", semanticTags:["自愛","包容","心情"], lines:["真正自愛的人，","不會與人計較。"]},
    {id:338, origId:338, content:"對自己要有信心，對他人要信任。", semanticTags:["信心","誠信","尊重"], lines:["對自己要有信心，","對他人要信任。"]},
    {id:339, origId:339, content:"「路」必須走方能到達；「事」必須做才能完成；「苦」必須受才可消除。", semanticTags:["行動","工作","磨練"], lines:["「路」必須走方能到達；","「事」必須做才能完成；","「苦」必須受才可消除。"]},
    {id:340, origId:340, content:"世間的海可以填平，但是人的鼻下橫，小小的一個嘴巴卻永遠填不滿。", semanticTags:["欲望","知足","說話"], lines:["世間的海可以填平，","但是人的鼻下橫，","小小的一個嘴巴","卻永遠填不滿。"]},
    {id:341, origId:341, content:"要想改造世界適合自己是過分要求，如我們不能稱心，或許可以知足。", semanticTags:["知足","包容","改變"], lines:["要想改造世界適合自己是過分要求，","如我們不能稱心，或許可以知足。"]},
    {id:342, origId:342, content:"遇到困境，一定要用更大的鬥志面對，惟有勇敢迎敵，才有機會致勝。", semanticTags:["勇氣","困難","積極"], lines:["遇到困境，一定要用更大的鬥志面對，","惟有勇敢迎敵，才有機會致勝。"]},
    {id:343, origId:343, content:"做事像做數學應用題，只會加減乘除，不會靈活應用，等於不會做。", semanticTags:["智慧","工作","處事"], lines:["做事像做數學應用題，","只會加減乘除，","不會靈活應用，","等於不會做。"]},
    {id:344, origId:344, content:"理直氣壯，得理不饒人者，不僅惹事生非，傷人傷己，甚至永遠無法化解仇恨，圓融人事。", semanticTags:["包容","修養","原諒","處事","衝突"], lines:["理直氣壯，得理不饒人者，","不僅惹事生非，傷人傷己，","甚至永遠無法化解仇恨，圓融人事。"]},
    {id:345, origId:345, content:"有多少力量，就做多少事，切莫等待，等待常會落空。", semanticTags:["本份","工作","積極"], lines:["有多少力量，就做多少事，","切莫等待，等待常會落空。"]},
    {id:346, origId:346, content:"路是人走出來的，千里之遙始於初步。", semanticTags:["行動","堅持","努力"], lines:["路是人走出來的，","千里之遙始於初步。"]},
    {id:347, origId:347, content:"人人若能彼此溝通，就能相安無事。假如多心、猜疑即成是非。", semanticTags:["溝通","平靜","衝突"], lines:["人人若能彼此溝通，","就能相安無事。","假如多心、猜疑即成是非。"]},
    {id:348, origId:348, content:"人常在什麼都可自由的時候，卻被這種隨心所欲的自由蒙蔽，虛擲時光而不覺。", semanticTags:["自由","自律","選擇","時間"], lines:["人常在什麼都可自由的時候，","卻被這種隨心所欲的自由蒙蔽，","虛擲時光而不覺。"]},
    {id:349, origId:349, content:"只要緣深，不怕緣來得遲；只要找到路，就不怕路遙遠。", semanticTags:["堅持","機會","方向"], lines:["只要緣深，不怕緣來得遲；","只要找到路，就不怕路遙遠。"]},
    {id:350, origId:350, content:"人生如蠟燭，即使有心，也要點燃，方能造福。", semanticTags:["付出","希望","光明"], lines:["人生如蠟燭，即使有心，","也要點燃，方能造福。"]},
    {id:351, origId:351, content:"存於心中自有的光明就是慧命。", semanticTags:["智慧","心情","光明"], lines:["存於心中自有的","光明就是慧命。"]},
    {id:352, origId:352, content:"付出愛心後要懂得感恩，懂得縮小自己。", semanticTags:["感恩","付出","愛心"], lines:["付出愛心後要","懂得感恩，","懂得縮小自己。"]},
    {id:353, origId:353, content:"愛心是每個人都有的，只是在觀念的開啟。", semanticTags:["愛心","善念","改變"], lines:["愛心是每個人都有的，","只是在觀念的開啟。"]},
    {id:354, origId:354, content:"對他人付出，會感到生命更踏實，更有意義，人生沒有絲毫的空虛。", semanticTags:["付出","生命","工作"], lines:["對他人付出，會感到","生命更踏實，更有意義，","人生沒有絲毫的空虛。"]},
    {id:355, origId:355, content:"沒有智慧，無法修福；在付出愛的同時，更感恩那些讓我們有機會付出的人。", semanticTags:["智慧","感恩","付出"], lines:["沒有智慧，無法修福；","在付出愛的同時，更感恩那些","讓我們有機會付出的人。"]},
    {id:356, origId:356, content:"修行要在人群中相互磨鍊，藉事鍊心；慈悲喜捨也是要從力行中，才能真正有所領悟。", semanticTags:["磨練","處事","行動"], lines:["修行要在人群中","相互磨鍊，藉事鍊心；","慈悲喜捨也是要從力行中，","才能真正有所領悟。"]},
    {id:357, origId:357, content:"人真的要能忍，不能忍耐的結果就是星火燎原。", semanticTags:["包容","修養","自律"], lines:["人真的要能忍，","不能忍耐的結果","就是星火燎原。"]},
    {id:358, origId:358, content:"內隨願，外隨緣，才能自在如願。", semanticTags:["平靜","解脫","自由"], lines:["內隨願，外隨緣，","才能自在如願。"]},
    {id:359, origId:359, content:"以親子之心教導學生，付出無限的關懷與愛心，教育不要只停留在知識的言教，除身教外，最重要是心教。", semanticTags:["付出","愛心","關懷","教育","父母","孝順"], lines:["以親子之心教導學生，","付出無限的關懷與愛心，","教育不要只停留在知識的言教，","除身教外，最重要是心教。"]},
    {id:360, origId:360, content:"應走而不走，非智；難行而能行，是勇；勇者但知「行所當行，為所應為」。", semanticTags:["勇氣","本份","行動"], lines:["應走而不走，非智；","難行而能行，是勇；","勇者但知「行所當行，為所應為」。"]},
    {id:361, origId:361, content:"正語就是要說真正的話、實在的話、誠懇的話。", semanticTags:["真誠","誠信","說話"], lines:["正語就是要說","真正的話、","實在的話、","誠懇的話。"]},
    {id:362, origId:362, content:"人之所以會痛苦是因為不滿足，對別人要求太多，而且不肯輕易原諒別人。", semanticTags:["原諒","知足","包容"], lines:["人之所以會痛苦","是因為不滿足，","對別人要求太多，","而且不肯輕易原諒別人。"]},
    {id:363, origId:363, content:"真正的智慧，在於坦誠的愛和彼此間的信賴，而不涉及任何利害關係。", semanticTags:["智慧","誠信","感情"], lines:["真正的智慧，在於坦誠的","愛和彼此間的信賴，","而不涉及任何利害關係。"]},
    {id:364, origId:364, content:"人生為人群付出多少，就得多少踏實感。", semanticTags:["付出","工作","生命"], lines:["人生為人群付出多少，","就得多少踏實感。"]},
    {id:365, origId:365, content:"生命的蠟燭要點滴不漏，充分發揮光明照耀人間。", semanticTags:["珍惜","大愛","光明"], lines:["生命的蠟燭要點滴不漏，","充分發揮光明照耀人間。"]},
    {id:366, origId:366, content:"愛的教育是愛他；教育他的同時，也要啟發他愛人的心。", semanticTags:["教育","愛心","付出"], lines:["愛的教育是愛他；","教育他的同時，","也要啟發他愛人的心。"]},
    {id:367, origId:367, content:"是非從人事中來，要把複雜的人事單純化，成為自我的教育。", semanticTags:["教育","轉念","衝突"], lines:["是非從人事中來，","要把複雜的人事單純化，","成為自我的教育。"]},
    {id:368, origId:368, content:"對人事的紛擾要如「手畫虛空，畫過無痕」。", semanticTags:["解脫","包容","平靜"], lines:["對人事的紛擾要如","「手畫虛空，畫過無痕」。"]},
    {id:369, origId:369, content:"生命如蠟燭，雖然點燃後生命不斷減損，但點燃自己才能照亮別人，生命也才有意義。", semanticTags:["大愛","希望","光明","價值"], lines:["生命如蠟燭，雖然點燃後","生命不斷減損，但點燃自己","才能照亮別人，生命也才有意義。"]},
    {id:370, origId:370, content:"人生的價值，不在於生命的長短，而在於能否發揮功能。", semanticTags:["價值","生命","付出","本份"], lines:["人生的價值，","不在於生命的長短，","而在於能否發揮功能。"]},
    {id:371, origId:371, content:"每個人心底都有一股清流，都有一塊福田，隱藏著豐沛的泉源。", semanticTags:["善念","平靜","心情"], lines:["每個人心底都有一股清流，","都有一塊福田，","隱藏著豐沛的泉源。"]},
    {id:372, origId:372, content:"義務的付出，在工作中會產生一種享受犧牲的快樂。", semanticTags:["快樂","付出","工作"], lines:["義務的付出，在工作中","會產生一種享受犧牲的快樂。"]},
    {id:373, origId:373, content:"人如果沒有得的心理，就不會有失的煩惱。", semanticTags:["煩惱","得失","解脫"], lines:["人如果沒有得的心理，","就不會有失的煩惱。"]},
    {id:374, origId:374, content:"不知足的人，即使享有人間最豐富的物質生活，也難遣心靈空虛之苦。", semanticTags:["知足","欲望","解脫"], lines:["不知足的人，即使享有","人間最豐富的物質生活，","也難遣心靈空虛之苦。"]},
    {id:375, origId:375, content:"愛慾愈熾，貪念愈多。", semanticTags:["欲望","自律","解脫"], lines:["愛慾愈熾，","貪念愈多。"]},
    {id:376, origId:376, content:"一切的法是用來修心，一切的物質是用來幫助生活。", semanticTags:["修養","心情","知足"], lines:["一切的法是用來修心，","一切的物質是用來幫助生活。"]},
    {id:377, origId:377, content:"方向正確即不再迷失，而心中自然產生一股永無休止不斷精進的意念。", semanticTags:["方向","堅持","正念"], lines:["方向正確即不再迷失，","而心中自然產生一股","永無休止不斷精進的意念。"]},
    {id:378, origId:378, content:"人心所起的喜怒哀樂即是煩惱，皆由心、口、意而來。", semanticTags:["煩惱","心情","自律"], lines:["人心所起的喜怒哀樂即是煩惱，","皆由心、口、意而來。"]},
    {id:379, origId:379, content:"人生的意義與價值，不在於存活世間的久長，而在於自己為世間付出多少。", semanticTags:["價值","生命","付出","本份"], lines:["人生的意義與價值，","不在於存活世間的久長，","而在於自己為世間付出多少。"]},
    {id:380, origId:380, content:"克盡做人的本分，在工作中得到快樂喜悅，就是最踏實、最幸福的人生。", semanticTags:["快樂","做人","工作"], lines:["克盡做人的本分，","在工作中得到快樂喜悅，","就是最踏實、最幸福的人生。"]},
    {id:381, origId:381, content:"命是可以改變的，掌握在自己手裡。", semanticTags:["轉念","行動","改變","命運"], lines:["命是可以改變的，","掌握在自己手裡。"]},
    {id:382, origId:382, content:"人應靜思反省，以撥開心靈的波瀾，發掘智慧的泉源。", semanticTags:["智慧","平靜","反省"], lines:["人應靜思反省，","以撥開心靈的波瀾，","發掘智慧的泉源。"]},
    {id:383, origId:383, content:"聰明不一定具備智慧，但是智慧一定包括聰明；聰明只是一種計量利弊得失的能力，貪婪詭詐也是聰明的象徵。", semanticTags:["智慧","解脫","修養","得失"], lines:["聰明不一定具備智慧，","但是智慧一定包括聰明；","聰明只是一種計量利弊得失的能力，","貪婪詭詐也是聰明的象徵。"]},
    {id:384, origId:384, content:"做事要保持三個原則：赤子的真心、駱駝的耐心、獅子的勇猛心。", semanticTags:["真誠","堅持","勇氣"], lines:["做事要保持三個原則：","赤子的真心、","駱駝的耐心、","獅子的勇猛心。"]},
    {id:385, origId:385, content:"人要祝福自己，祝福自己就不要唉聲嘆氣。", semanticTags:["轉念","歡喜","抱怨"], lines:["人要祝福自己，","祝福自己就不要唉聲嘆氣。"]},
    {id:386, origId:386, content:"別人罵我、不諒解我、毀謗我，我反而應興起一分感謝的心理，感謝他們給我修行的境界。", semanticTags:["感恩","轉念","包容"], lines:["別人罵我、不諒解我、毀謗我，","我反而應興起一分感謝的心理，","感謝他們給我修行的境界。"]},
    {id:387, origId:387, content:"讚嘆別人就是莊嚴自己，批評別人就是作賤自己。", semanticTags:["批評","讚美","尊重"], lines:["讚嘆別人就是莊嚴自己，","批評別人就是作賤自己。"]},
    {id:388, origId:388, content:"師長的責任，只是教導；實踐的道路，必須自己去走。", semanticTags:["責任","教育","行動"], lines:["師長的責任，只是教導；","實踐的道路，必須自己去走。"]},
    {id:389, origId:389, content:"微笑是世界共通的語言，愛的表現。", semanticTags:["態度","愛心","溫暖"], lines:["微笑是世界共通的語言，","愛的表現。"]},
    {id:390, origId:390, content:"凡夫都是因為心量太小，所以無法容納其他的人。", semanticTags:["包容","修養","謙虛"], lines:["凡夫都是因為心量太小，","所以無法容納其他的人。"]},
    {id:391, origId:391, content:"只怕力量不夠，不怕做的工作太多。", semanticTags:["工作","責任","努力"], lines:["只怕力量不夠，","不怕做的工作太多。"]},
    {id:392, origId:392, content:"面對紛雜的氣氛，只要抱持感恩心，就不會感覺煩躁。尤其是愈感恩，就會愈覺得做好。", semanticTags:["感恩","平靜","轉念"], lines:["面對紛雜的氣氛，","只要抱持感恩心，","就不會感覺煩躁。","尤其是愈感恩，","就會愈覺得做好。"]},
    {id:393, origId:393, content:"在人事歷練中不求聰明，但求智慧；智慧是人心最清淨、最完美的一念。本性、智慧具足，就能分辨人事體會真理。", semanticTags:["智慧","修養","考驗"], lines:["在人事歷練中不求聰明，但求智慧；","智慧是人心最清淨、最完美的一念。","本性、智慧具足，就能分辨人事體會真理。"]},
    {id:394, origId:394, content:"能懂得適時適機運用所得，利益人群，廣結善緣，才是成功圓滿的人生。", semanticTags:["利益","成就","處事"], lines:["能懂得適時適機運用所得，","利益人群，廣結善緣，","才是成功圓滿的人生。"]},
    {id:395, origId:395, content:"內能自謙是功，外能禮讓是德。", semanticTags:["謙虛","禮讓","修養"], lines:["內能自謙是功，","外能禮讓是德。"]},
    {id:396, origId:396, content:"只有享受不是福氣。有能力為他人付出，才是真正恆常的福。", semanticTags:["付出","惜福","幸福"], lines:["只有享受不是福氣。","有能力為他人付出，","才是真正恆常的福。"]},
    {id:397, origId:397, content:"起心動念無不是業；開口動舌、舉手投足，無不是罪。", semanticTags:["謹慎","自律","修養"], lines:["起心動念無不是業；", "開口動舌、舉手投足，", "無不是罪。"]},
    {id:398, origId:398, content:"要讓心中常保餘地，切莫自滿而有所溢。", semanticTags:["謙虛","包容","反省"], lines:["要讓心中常保餘地，","切莫自滿而有所溢。"]},
    {id:399, origId:399, content:"對自己有幻想的人叫愚，對別人有幻想的人叫痴。", semanticTags:["反省","智慧","改過"], lines:["對自己有幻想的人叫愚，","對別人有幻想的人叫痴。"]},
    {id:400, origId:400, content:"心地空時，宇宙虛空都可容納；心地滿時，容不了一滴水、一粒沙。", semanticTags:["包容","謙虛","平靜"], lines:["心地空時，宇宙虛空都可容納；","心地滿時，容不了一滴水、一粒沙。"]},
    {id:401, origId:401, content:"人命呼吸間，唯有在分秒間警惕自己毋怠毋懈，方能不斷向前邁進。", semanticTags:["時間","珍惜","自律","堅持"], lines:["人命呼吸間，","唯有在分秒間","警惕自己毋怠毋懈，","方能不斷向前邁進。"]},
    {id:402, origId:402, content:"過去的努力有現在的成就；未來的展望是現在的動作。", semanticTags:["努力","成就","方向","時間"], lines:["過去的努力有現在的成就；","未來的展望是現在的動作。"]},
    {id:403, origId:403, content:"人生無常，要趕緊行善修行。", semanticTags:["時間","珍惜","生命","善念"], lines:["人生無常，","要趕緊行善修行。"]},
    {id:404, origId:404, content:"做人要有踏實感，不要只有成就感；踏踏實實地做人，心中多舒服。", semanticTags:["做人","態度","心情"], lines:["做人要有踏實感，", "不要只有成就感；", "踏踏實實地做人，", "心中多舒服。"]},
    {id:405, origId:405, content:"做人要做到三不靠：不靠權力，不靠地位，不靠金錢。", semanticTags:["做人","自律","尊嚴"], lines:["做人要做到三不靠：","不靠權力，","不靠地位，","不靠金錢。"]},
    {id:406, origId:406, content:"難行能行、難捨能捨、難為能為，才能昇華自我的人格。", semanticTags:["努力","堅持","修養","人格"], lines:["難行能行、難捨能捨、","難為能為，才能","昇華自我的人格。"]},
    {id:407, origId:407, content:"用鼓掌的雙手做環保。", semanticTags:["行動","珍惜","付出"], lines:["用鼓掌的雙手做環保。"]},
    {id:408, origId:408, content:"善於利用時間的人，無時無刻不是修持參禪的好機緣。", semanticTags:["時間", "珍惜", "專注"], lines:["善於利用時間的人，", "無時無刻不是", "修持參禪的好機緣。"]},
    {id:409, origId:409, content:"心平靜，當下就是淨土。", semanticTags:["平靜", "安定", "心情"], lines:["心平靜，", "當下就是淨土。"]},
    {id:410, origId:410, content:"真正的心好，應該是非常自然，沒有一絲一毫地考慮，馬上伸出援手去扶助別人。", semanticTags:["善念", "行動", "關懷", "付出"], lines:["真正的心好，應該是非常自然，", "沒有一絲一毫地考慮，", "馬上伸出援手去扶助別人。"]},
    {id:411, origId:411, content:"布施若不是真正心存喜捨，則非但沒有功德，反增煩惱。", semanticTags:["付出", "歡喜", "煩惱", "無私"], lines:["布施若不是真正心存喜捨，", "則非但沒有功德，反增煩惱。"]},
    {id:412, origId:412, content:"人人本具菩薩心，也具有和菩薩同等的精神與力量。", semanticTags:["信心", "善念", "自愛"], lines:["人人本具菩薩心，也具有和", "菩薩同等的精神與力量。"]},
    {id:413, origId:413, content:"一個人面臨絕境時，還能心存感恩很是難得。永保感恩心付出的人，比較不會陷入絕境。", semanticTags:["感恩", "困難", "希望", "付出"], lines:["一個人面臨絕境時，", "還能心存感恩很是難得。", "永保感恩心付出的人，", "比較不會陷入絕境。"]},
    {id:414, origId:414, content:"「戒」是不起心動念；「定」是臨危不亂；「慧」能運心轉境。", semanticTags:["自律", "智慧", "平靜", "修養"], lines:["「戒」是不起心動念；", "「定」是臨危不亂；", "「慧」能運心轉境。"]},
    {id:415, origId:415, content:"心無邪思，意無邪念，即常自在；心正則邪不侵。", semanticTags:["正念", "善念", "自律", "安定", "解脫"], lines:["心無邪思，意無邪念，", "即常自在；心正則邪不侵。"]},
    {id:416, origId:416, content:"理想要放在遠方，腳步要落實現在。", semanticTags:["方向", "行動", "努力"], lines:["理想要放在遠方，", "腳步要落實現在。"]},
    {id:417, origId:417, content:"心迷就會苦，心悟就自在。", semanticTags:["轉念", "智慧", "解脫"], lines:["心迷就會苦，", "心悟就自在。"]},
    {id:418, origId:418, content:"陪伴父母要歡喜，而不是應付責任。", semanticTags:["孝順", "父母", "歡喜", "責任"], lines:["陪伴父母要歡喜，", "而不是應付責任。"]},
    {id:419, origId:419, content:"千里之路，必須從第一步開始；聖人的境域，也是自凡夫起步。", semanticTags:["行動", "堅持", "努力", "方向"], lines:["千里之路，必須從第一步開始；", "聖人的境域，也是自凡夫起步。"]},
    {id:420, origId:420, content:"遭受別人批評時，先問自心是否無愧？無愧則心安。", semanticTags:["批評", "反省", "無愧", "平靜"], lines:["遭受別人批評時，", "先問自心是否無愧？", "無愧則心安。"]},
    {id:421, origId:421, content:"感恩他人就是美化自己。", semanticTags:["感恩", "修養", "欣賞"], lines:["感恩他人就是美化自己。"]},
    {id:422, origId:422, content:"學佛，就是要學會及時改正錯誤的觀念。", semanticTags:["改過", "反省", "學習"], lines:["學佛，就是要學會", "及時改正錯誤的觀念。"]},
    {id:423, origId:423, content:"人生幾十年的成就，都是由每一天的言行累積而成。所以，要照顧好每一天的言行。", semanticTags:["成就", "謹慎", "自律", "說話"], lines:["人生幾十年的成就，都是由", "每一天的言行累積而成。", "所以，要照顧好每一天的言行。"]},
    {id:424, origId:424, content:"聽話、說話要完整，不要只揀前一句、後一句，合起來剛好尖尖的刺進人心。", semanticTags:["說話", "溝通", "謹慎", "衝突"], lines:["聽話、說話要完整，", "不要只揀前一句、後一句，", "合起來剛好尖尖的刺進人心。"]},
    {id:425, origId:425, content:"人生若精神文化充足富有，縱使物質生活平淡，也會感到樂在其中。", semanticTags:["知足", "快樂", "價值"], lines:["人生若精神文化充足富有，", "縱使物質生活平淡，", "也會感到樂在其中。"]},
    {id:426, origId:426, content:"什麼都沒做，就是空過的人生；若能不斷付出利益人群，就是大好的人生。", semanticTags:["付出", "行動", "利益", "價值"], lines:["什麼都沒做，就是空過的人生；", "若能不斷付出利益人群，", "就是大好的人生。"]},
    {id:427, origId:427, content:"感恩可以打開我們的心結，並且啟發我們的悲心。", semanticTags:["感恩", "愛心", "轉念"], lines:["感恩可以打開我們的心結，", "並且啟發我們的悲心。"]},
    {id:428, origId:428, content:"以歡喜心做事，即使忙碌卻不感到辛苦，反而覺得甘甜。", semanticTags:["歡喜", "工作", "態度"], lines:["以歡喜心做事，即使忙碌", "卻不感到辛苦，反而覺得甘甜。"]},
    {id:429, origId:429, content:"好事，需要你、我、他共同來成就。所以，不要有你、我、他的成見。", semanticTags:["合作", "團結", "包容"], lines:["好事，需要你、我、他共同來成就。", "所以，不要有你、我、他的成見。"]},
    {id:430, origId:430, content:"要擁有很可愛的人生，就要自己先去愛人。", semanticTags:["愛心", "付出", "幸福"], lines:["要擁有很可愛的人生，", "就要自己先去愛人。"]},
    {id:431, origId:431, content:"以親切的愛心去關懷別人，這分愛心便是造福的種子。", semanticTags:["關懷", "愛心", "善念", "付出"], lines:["以親切的愛心去關懷別人，", "這分愛心便是造福的種子。"]},
    {id:432, origId:432, content:"行善是本分、付出無所求，不執著「善有善報」，自然輕安自在。", semanticTags:["本份", "付出", "無私", "安定"], lines:["行善是本分、付出無所求，", "不執著「善有善報」，", "自然輕安自在。"]},
    {id:433, origId:433, content:"退讓一步以成全別人，即是修養，即是修行。", semanticTags:["禮讓", "修養", "包容"], lines:["退讓一步以成全別人，", "即是修養，即是修行。"]},
    {id:434, origId:434, content:"心中有信，願力無窮；心中無私，其福無量。", semanticTags:["信心", "無私", "幸福"], lines:["心中有信，願力無窮；", "心中無私，其福無量。"]},
    {id:435, origId:435, content:"把貪念轉為滿足，把滿足化作慈悲。", semanticTags:["欲望", "知足", "大愛", "轉念"], lines:["把貪念轉為滿足，", "把滿足化作慈悲。"]},
    {id:436, origId:436, content:"我們要接受天下人、事、物的磨練，方能成為一個堅強的人。", semanticTags:["磨練", "考驗", "毅力"], lines:["我們要接受天下", "人、事、物的磨練，", "方能成為一個堅強的人。"]},
    {id:437, origId:437, content:"處理事情，感情要蘊藏在理智中；與人相處，則要把感情表現在理智上。", semanticTags:["處事", "溝通", "感情", "智慧"], lines:["處理事情，感情", "要蘊藏在理智中；", "與人相處，則要把", "感情表現在理智上。"]},
    {id:438, origId:438, content:"有一分心，就有一分力量。", semanticTags:["信心", "行動", "努力"], lines:["有一分心，就有一分力量。"]},
    {id:439, origId:439, content:"人人本有清淨純真的佛性，只因煩惱無明而遮蔽了。", semanticTags:["煩惱", "善念", "智慧"], lines:["人人本有清淨純真的佛性，", "只因煩惱無明而遮蔽了。"]},
    {id:440, origId:440, content:"菩薩不是土塑木刻的形象，真正的菩薩能做事、能說話、能吃飯，能尋聲救苦隨處現身。", semanticTags:["行動", "關懷", "付出"], lines:["菩薩不是土塑木刻的形象，", "真正的菩薩能做事、能說話、", "能吃飯，能尋聲救苦隨處現身。"]},
    {id:441, origId:441, content:"最平淡的日子，心裡最安定。", semanticTags:["安定", "平靜", "知足"], lines:["最平淡的日子，", "心裡最安定。"]},
    {id:442, origId:442, content:"發脾氣是短暫的發瘋。", semanticTags:["生氣", "修養", "自律"], lines:["發脾氣是短暫的發瘋。"]},
    {id:443, origId:443, content:"以愛待人、以慈對人，則不惹人怨，亦能結好緣。", semanticTags:["愛心", "關懷", "包容"], lines:["以愛待人、以慈對人，", "則不惹人怨，亦能結好緣。"]},
    {id:444, origId:444, content:"人既然生在世間，就不能離開眾緣，修行也不能離群隱世。", semanticTags:["處事", "合作", "修養"], lines:["人既然生在世間，", "就不能離開眾緣，", "修行也不能離群隱世。"]},
    {id:445, origId:445, content:"做人固然不應將自我看得太重，但也不要自輕己靈。", semanticTags:["謙虛", "自愛", "信心"], lines:["做人固然不應將", "自我看得太重，", "但也不要自輕己靈。"]},
    {id:446, origId:446, content:"時時感恩，處處感恩，人人感恩，事事感恩。", semanticTags:["感恩", "惜福", "歡喜"], lines:["時時感恩，處處感恩，", "人人感恩，事事感恩。"]},
    {id:447, origId:447, content:"平安就是福，助人就是慧。", semanticTags:["幸福", "智慧", "付出"], lines:["平安就是福，", "助人就是慧。"]},
    {id:448, origId:448, content:"「不斷地付出就是在造福，面對人事就是在修慧」；若能福慧雙具，就是慧命增長。", semanticTags:["付出", "智慧", "處事"], lines:["「不斷地付出就是在造福，", "面對人事就是在修慧」；", "若能福慧雙具，就是慧命增長。"]},
    {id:449, origId:449, content:"合心為善，和氣付出；互愛讚歎，伸手協力。", semanticTags:["合作", "團結", "讚美", "付出"], lines:["合心為善，和氣付出；", "互愛讚歎，伸手協力。"]},
    {id:450, origId:450, content:"珍惜每一分、每一秒，踏踏實實為社會付出愛。", semanticTags:["珍惜", "時間", "付出", "愛心"], lines:["珍惜每一分、每一秒，", "踏踏實實為社會付出愛。"]},
    {id:451, origId:451, content:"人生若能減低欲望，生活上便沒有什麼值得計較！", semanticTags:["欲望", "知足", "得失"], lines:["人生若能減低欲望，", "生活上便沒有什麼值得計較！"]},
    {id:452, origId:452, content:"人最難看得見的，就是自己。", semanticTags:["反省", "謙虛", "智慧"], lines:["人最難看得見的，", "就是自己。"]},
    {id:453, origId:453, content:"煩惱就像一條毒蛇睡在人的心中。一觸動它，蛇就會咬人。", semanticTags:["煩惱", "心情", "平靜"], lines:["煩惱就像一條毒蛇", "睡在人的心中。", "一觸動它，蛇就會咬人。"]},
    {id:454, origId:454, content:"凡事對機即是好。", semanticTags:["處事", "智慧", "選擇"], lines:["凡事對機即是好。"]},
    {id:455, origId:455, content:"做好事，不在於一定做多少，應該做的就要做。", semanticTags:["本份", "行動", "善念"], lines:["做好事，不在於", "一定做多少，", "應該做的就要做。"]},
    {id:456, origId:456, content:"增一分感恩心，即減一分猜疑心。", semanticTags:["感恩", "包容", "信心"], lines:["增一分感恩心，", "即減一分猜疑心。"]},
    {id:457, origId:457, content:"多做好事，才能開闊心靈的天地。", semanticTags:["善念", "行動", "心情"], lines:["多做好事，才能", "開闊心靈的天地。"]},
    {id:458, origId:458, content:"解除人間的災難，一定要從改善人心做起。", semanticTags:["善念", "改變", "教育"], lines:["解除人間的災難，", "一定要從改善人心做起。"]},
    {id:459, origId:459, content:"面對業力不要埋怨；要用寬諒和樂的心來代替埋怨。", semanticTags:["抱怨", "包容", "轉念", "歡喜"], lines:["面對業力不要埋怨；", "要用寬諒和樂的心", "來代替埋怨。"]},
    {id:460, origId:460, content:"對人有疑心，就無法愛人；對人有疑念，就無法原諒人；對人有疑惑，就無法相信人。", semanticTags:["信心", "原諒", "愛心", "溝通"], lines:["對人有疑心，就無法愛人；", "對人有疑念，就無法原諒人；", "對人有疑惑，就無法相信人。"]},
    {id:461, origId:461, content:"美滿的人生，不在物質、權勢、名利及地位，而在人與人之間的關愛與情誼。", semanticTags:["幸福", "關懷", "名利", "感情"], lines:["美滿的人生，不在", "物質、權勢、名利及地位，", "而在人與人之間的關愛與情誼。"]},
    {id:462, origId:462, content:"凡夫追求財物，聖人追求真理。", semanticTags:["名利", "欲望", "智慧"], lines:["凡夫追求財物，", "聖人追求真理。"]},
    {id:463, origId:463, content:"要有過程，不要有手段；要有目標，不要有目的。", semanticTags:["處事", "方向", "真誠"], lines:["要有過程，不要有手段；", "要有目標，不要有目的。"]},
    {id:464, origId:464, content:"心量大福報就大。", semanticTags:["包容", "幸福", "修養"], lines:["心量大福報就大。"]},
    {id:465, origId:465, content:"有所求的愛，是無法永久存在的。能夠永久存在的，是那份無形、無染且無求的愛。", semanticTags:["愛心", "無私", "感情"], lines:["有所求的愛，", "是無法永久存在的。", "能夠永久存在的，是那份", "無形、無染且無求的愛。"]},
    {id:466, origId:466, content:"布施就好比汲取井水：唯有不斷地布施，才能造福、增福。", semanticTags:["付出", "無私", "善念"], lines:["布施就好比汲取井水：", "唯有不斷地布施，", "才能造福、增福。"]},
    {id:467, origId:467, content:"不是什麼都不理就叫無爭，而是要與人合心、和氣、互愛、協力。", semanticTags:["合作", "團結", "包容", "溝通"], lines:["不是什麼都不理就叫", "無爭，而是要與人", "合心、和氣、互愛、協力。"]},
    {id:468, origId:468, content:"把自己的本分事做好，歡喜接受所面臨的一切。過一分鐘即消一分災。", semanticTags:["本份", "歡喜", "態度"], lines:["把自己的本分事做好，", "歡喜接受所面臨的一切。", "過一分鐘即消一分災。"]},
    {id:469, origId:469, content:"社會的進步不是用喊出來的，是做出來的。", semanticTags:["行動", "努力", "改變"], lines:["社會的進步", "不是用喊出來的，", "是做出來的。"]},
    {id:470, origId:470, content:"聽到別人批評，要自我反省；有錯就改，沒錯則歡喜包容。", semanticTags:["批評", "反省", "改過", "包容"], lines:["聽到別人批評，要自我反省；", "有錯就改，沒錯則歡喜包容。"]},
    {id:471, origId:471, content:"想要家庭吉祥、和睦，就應該常常起歡喜心，天天為自己的家庭祝福。", semanticTags:["家庭", "歡喜", "幸福"], lines:["想要家庭吉祥、和睦，", "就應該常常起歡喜心，", "天天為自己的家庭祝福。"]},
    {id:472, origId:472, content:"真正的禪，是在日常生活中不起煩惱妄想。", semanticTags:["平靜", "煩惱", "正念"], lines:["真正的禪，", "是在日常生活中", "不起煩惱妄想。"]},
    {id:473, origId:473, content:"心如鏡。雖外在景物不斷轉變，鏡面卻不會轉動，此即境轉而心不轉。", semanticTags:["平靜", "安定", "修養"], lines:["心如鏡。雖外在", "景物不斷轉變，", "鏡面卻不會轉動，", "此即境轉而心不轉。"]},
    {id:474, origId:474, content:"無量功德是在日積月累中，分毫累積聚集而成。", semanticTags:["功德", "堅持", "善念"], lines:["無量功德是在日積月累中，", "分毫累積聚集而成。"]},
    {id:475, origId:475, content:"聽到好話要感恩，聽到壞話要善解。", semanticTags:["感恩", "包容", "說話"], lines:["聽到好話要感恩，", "聽到壞話要善解。"]}
];
